insert into public.game_questions (category, difficulty, q, options, correct, explain, durable, source)
values
  ('israel_league', 'easy', 'איזו קבוצה זכתה במספר הגדול ביותר של אליפויות בליגה הבכירה בכדורסל בישראל?', array['מכבי תל אביב', 'הפועל ירושלים', 'הפועל תל אביב', 'הפועל חולון'], 0, 'מכבי לקחה כ-80% מכל האליפויות בתולדות הליגה — שיעור שאין לו אח ורע בשום ליגה בכירה באירופה.', true, 'ויקיפדיה – ליגת העל בכדורסל'),
  ('israel_league', 'medium', 'איזו קבוצה שברה ב-1993 את רצף האליפויות הארוך של מכבי תל אביב?', array['הפועל גליל עליון', 'הפועל ירושלים', 'מכבי חיפה', 'הפועל חולון'], 0, 'באותה עונה, שכונתה «עונת הדובדבנים», גליל עליון הדיחה את מכבי בחצי הגמר 2:3 בדרך לתואר.', true, 'ויקיפדיה – הפועל גליל עליון (כדורסל)'),
  ('israel_league', 'medium', 'כמה אליפויות רצופות זכתה מכבי תל אביב עד שהרצף נשבר ב-1993?', array['12', '17', '23', '30'], 2, 'הרצף החל ב-1970 ונמשך עד 1992 — בכל אותן שנים אף קבוצה אחרת לא הרימה את גביע האליפות.', true, 'ויקיפדיה – מכבי תל אביב (כדורסל)'),
  ('israel_league', 'hard', 'מי אימן את הפועל גליל עליון באליפות ההיסטורית של 1993?', array['פיני גרשון', 'צבי שרף', 'דויד בלאט', 'ראלף קליין'], 0, 'גרשון סיים את הקריירה עם שמונה אליפויות ישראל — אחת עם גליל עליון וכל השאר עם מכבי תל אביב.', true, 'ויקיפדיה – פיני גרשון'),
  ('israel_league', 'medium', 'באיזו שנה זכתה הפועל ירושלים באליפות הראשונה בתולדותיה?', array['2004', '2010', '2015', '2017'], 2, 'המועדון נוסד ב-1943, כך שהתואר הראשון הגיע רק אחרי 72 שנות המתנה.', true, 'ויקיפדיה – הפועל ירושלים (כדורסל)'),
  ('israel_league', 'hard', 'מול איזו קבוצה שיחקה הפועל ירושלים בגמר האליפות הראשון שלה ב-2015?', array['מכבי תל אביב', 'הפועל אילת', 'הפועל חולון', 'מכבי חיפה'], 1, 'זה היה גמר נדיר: אף אחת משתי הקבוצות לא זכתה באליפות לפני כן.', true, 'ויקיפדיה – הפועל ירושלים (כדורסל)'),
  ('israel_league', 'hard', 'מי היה המאמן שהוביל את הפועל ירושלים לאליפות 2015?', array['דני פרנקו', 'שרון דרוקר', 'עודד קטש', 'גיא גודס'], 0, 'שנתיים אחר כך זכתה ירושלים באליפות שנייה, הפעם תחת האיטלקי סימונה פיאניג''אני.', true, 'ויקיפדיה – הפועל ירושלים (כדורסל)'),
  ('israel_league', 'medium', 'באיזו עונה זכתה מכבי חיפה באליפות היחידה בתולדותיה?', array['2007/08', '2009/10', '2012/13', '2015/16'], 2, 'התואר הגיע 60 שנה אחרי הקמת המועדון, בניצחון 79:86 על מכבי תל אביב.', true, 'ויקיפדיה – גמר ליגת העל 2012/13'),
  ('israel_league', 'hard', 'היכן נערך משחק גמר האליפות של 2013 שבו זכתה מכבי חיפה?', array['היכל יד אליהו', 'היכל רוממה בחיפה', 'פיס ארנה ירושלים', 'היכל טוטו חולון'], 1, 'האליפות הוכרעה אז במשחק בודד ולא בסדרה — פורמט שהיה נהוג בליגה באותן שנים.', true, 'ויקיפדיה – גמר ליגת העל 2012/13'),
  ('israel_league', 'medium', 'איזו קבוצה זכתה באליפות 2016 — התואר הראשון והיחיד שלה עד היום?', array['מכבי ראשון לציון', 'בני הרצליה', 'הפועל אילת', 'עירוני נהריה'], 0, 'ראשון ניצחה 77:83 את הפועל ירושלים — ועשתה זאת דווקא בפיס ארנה, האולם הביתי של היריבה, מול 11,000 צופים.', true, 'ויקיפדיה – פיינל פור 2016'),
  ('israel_league', 'hard', 'מי אימן את מכבי ראשון לציון באליפות 2016?', array['אריק שיבק', 'דן שמיר', 'עודד קטש', 'ברק פלג'], 0, 'בגמר בלט דריל מונרו עם 29 נקודות, שהפכו אותו למצטיין הפיינל פור.', true, 'ויקיפדיה – פיינל פור 2016'),
  ('israel_league', 'medium', 'איזו קבוצה זכתה באליפות 2010 והפתיעה את כל הליגה?', array['הפועל גלבוע גליל', 'הפועל חולון', 'בני הרצליה', 'מכבי חיפה'], 0, 'הקבוצה מהגליל ניצחה בגמר 77:90 את מכבי תל אביב — והאולם הביתי שלה בגן נר מכיל רק כ-2,100 מקומות.', true, 'ויקיפדיה – הפועל גלבוע גליל'),
  ('israel_league', 'hard', 'מי היה המאמן של הפועל גלבוע גליל באליפות 2010?', array['עודד קטש', 'פיני גרשון', 'שרון דרוקר', 'ארז אדלשטיין'], 0, 'קטש, שהיה קודם לכן אחד השחקנים הטובים בישראל, לקח אליפות באחת מעונותיו הראשונות כמאמן ראשי.', true, 'ויקיפדיה – הפועל גלבוע גליל'),
  ('israel_league', 'medium', 'באילו שתי עונות זכתה הפועל חולון באליפות המדינה?', array['2008 ו-2022', '2005 ו-2015', '2010 ו-2018', '2008 ו-2017'], 0, 'ב-2008 הפילה חולון את מכבי תל אביב בגמר, וב-2022 גברה בסדרת הגמר על בני הרצליה.', true, 'ויקיפדיה – הפועל חולון (כדורסל)'),
  ('israel_league', 'hard', 'בכמה נקודות ניצחה הפועל חולון את מכבי תל אביב בגמר האליפות של 2008?', array['נקודה אחת', 'שלוש נקודות', 'שש נקודות', 'עשר נקודות'], 0, 'התוצאה הייתה 72:73, והסל המכריע נקלע על ידי מאליק דיקסון בשניות האחרונות.', true, 'ויקיפדיה – הפועל חולון (כדורסל)'),
  ('israel_league', 'medium', 'הפועל תל אביב זכתה בחמש אליפויות. באיזה עשור הן הושגו כולן?', array['שנות ה-50', 'שנות ה-60', 'שנות ה-80', 'שנות ה-90'], 1, 'התואר האחרון הגיע בעונת 1968/69 — מאז הקבוצה האדומה עדיין ממתינה לאליפות נוספת.', true, 'ויקיפדיה – הפועל תל אביב (כדורסל)'),
  ('israel_league', 'easy', 'מדוע עונת 2024/25 בליגת העל הסתיימה בלי אלופה?', array['הליגה פשטה רגל', 'משחק ההכרעה בגמר לא התקיים בגלל המלחמה', 'שתי הקבוצות הורדו בנקודות', 'הגמר הסתיים בתיקו'], 1, 'מכבי תל אביב והפועל ירושלים הגיעו לסדרת הגמר, אך היא נעצרה באמצע ואף קבוצה לא הוכתרה.', true, 'מנהלת ליגת העל, basket.co.il'),
  ('israel_league', 'easy', 'איזו קבוצה זכתה באליפות עונת 2025/26?', array['מכבי תל אביב', 'הפועל תל אביב', 'הפועל ירושלים', 'הפועל חולון'], 0, 'מכבי ניצחה בסדרת הגמר 1:3 את הפועל תל אביב, וזו הייתה האליפות ה-58 שלה.', true, 'ויקיפדיה – עונת 2025/2026 בליגת העל'),
  ('israel_league', 'easy', 'איזו קבוצה זכתה בהכי הרבה גביעי מדינה בכדורסל?', array['מכבי תל אביב', 'הפועל ירושלים', 'הפועל תל אביב', 'בני הרצליה'], 0, 'מכבי הרימה את הגביע יותר מ-45 פעמים — כמעט שלוש מכל ארבע פעמים שהתחרות נערכה.', true, 'ויקיפדיה – גביע המדינה בכדורסל'),
  ('israel_league', 'medium', 'איזו קבוצה נמצאת במקום השני במספר הזכיות בגביע המדינה בכדורסל?', array['הפועל ירושלים', 'הפועל תל אביב', 'הפועל חולון', 'בני הרצליה'], 0, 'הגביע הראשון של ירושלים הגיע ב-1996 — כמעט 20 שנה לפני האליפות הראשונה שלה.', true, 'ויקיפדיה – גביע המדינה בכדורסל'),
  ('israel_league', 'hard', 'באיזה עשור נערך גביע המדינה בכדורסל בפעם הראשונה?', array['שנות ה-40', 'שנות ה-50', 'שנות ה-60', 'שנות ה-70'], 1, 'הגמר הראשון נערך בעונת 1955/56 והסתיים בניצחון מכבי תל אביב על הפועל תל אביב.', true, 'ויקיפדיה – גביע המדינה בכדורסל'),
  ('israel_league', 'hard', 'באילו שנים זכתה בני הרצליה בגביע המדינה בכדורסל?', array['1995 ו-2022', '1988 ו-2010', '2005 ו-2019', '1995 ו-2008'], 0, 'בין שתי הזכיות עברו 27 שנה — אחד הפערים הארוכים ביותר בין תארים בכדורסל הישראלי.', true, 'ויקיפדיה – גביע המדינה בכדורסל'),
  ('israel_league', 'hard', 'הפועל גליל עליון זכתה בשני גביעי מדינה. באילו שנים?', array['1988 ו-1992', '1993 ו-1996', '1985 ו-1990', '1992 ו-1998'], 0, 'שני הגביעים הגיעו עוד לפני האליפות המפורסמת של 1993 — הקבוצה מהצפון הייתה כוח אמיתי באותה תקופה.', true, 'ויקיפדיה – הפועל גליל עליון (כדורסל)'),
  ('israel_league', 'easy', 'מהו האולם הביתי של מכבי תל אביב בכדורסל?', array['היכל מנורה מבטחים (יד אליהו)', 'פיס ארנה ירושלים', 'היכל טוטו חולון', 'היכל רוממה'], 0, 'האולם נפתח בספטמבר 1963 ומכיל 10,383 מקומות ישיבה.', true, 'ויקיפדיה – היכל מנורה מבטחים'),
  ('israel_league', 'easy', 'מהו אולם הכדורסל הגדול ביותר בישראל?', array['פיס ארנה ירושלים', 'היכל מנורה מבטחים', 'היכל טוטו חולון', 'היכל רוממה'], 0, 'הארנה בשכונת מלחה נחנכה ב-2014 ומכילה כ-11,000 צופים.', true, 'ויקיפדיה – פיס ארנה ירושלים'),
  ('israel_league', 'easy', 'אילו שתי קבוצות כדורסל חולקות את היכל מנורה מבטחים בתל אביב?', array['מכבי תל אביב והפועל תל אביב', 'מכבי תל אביב ובני הרצליה', 'הפועל תל אביב ומכבי רמת גן', 'מכבי תל אביב ומכבי ראשון לציון'], 0, 'שתי היריבות הגדולות של העיר משחקות על אותו פרקט — מצב נדיר מאוד בכדורסל האירופי.', true, 'ויקיפדיה – היכל מנורה מבטחים'),
  ('israel_league', 'hard', 'מי היה מאמן מכבי תל אביב בזכייה הראשונה באליפות אירופה ב-1977?', array['ראלף קליין', 'רודי ד''אמיקו', 'פיני גרשון', 'צבי שרף'], 0, 'קליין אימן את מכבי בין 1976 ל-1980 וזכה בפרס ישראל על תרומתו לספורט; ד''אמיקו הביא את התואר האירופי הבא, ב-1981.', true, 'ויקיפדיה – מכבי תל אביב (כדורסל), פרסי ישראל'),
  ('israel_league', 'easy', 'מהו שם החסות הרשמי של הליגה הבכירה בכדורסל בישראל?', array['ליגת ווינר סל', 'ליגת טוטו', 'ליגת פיס', 'ליגת ישראכרט'], 0, 'השם מגיע מהחסות של מפעל ההימורים בספורט, ולכן רבים פשוט קוראים לה «ליגת ווינר».', false, 'ויקיפדיה – ליגת העל בכדורסל'),
  ('israel_league', 'medium', 'באיזו שנה הוקמה הליגה הארצית הבכירה לכדורסל בישראל?', array['1948', '1954', '1963', '1971'], 1, 'מאז נערכו יותר מ-70 עונות — עונת 2025/26 הייתה ה-72 במספר.', true, 'ויקיפדיה – ליגת העל בכדורסל'),
  ('israel_league', 'easy', 'עד סוף עונת 2025/26, בכמה אליפויות אירופה (יורוליג) זכתה מכבי תל אביב?', array['3', '4', '6', '9'], 2, 'התארים הגיעו בשנים 1977, 1981, 2001, 2004, 2005 ו-2014.', true, 'ויקיפדיה – מכבי תל אביב (כדורסל)'),
  ('israel_league', 'easy', 'מה אמר טל ברודי אחרי הניצחון ההיסטורי על צסק"א מוסקבה ב-1977?', array['«אנחנו על המפה»', '«אנחנו אלופי אירופה»', '«הלילה כולנו ישראלים»', '«זה רק ההתחלה»'], 0, 'המשפט המלא היה «אנחנו על המפה ואנחנו נשארים על המפה — לא רק בספורט, בהכל», והוא נכנס לשפה העברית.', true, 'ויקיפדיה – טל ברודי, כאן ארכיון'),
  ('israel_league', 'hard', 'היכן נערך המשחק המפורסם שבו ניצחה מכבי תל אביב את צסק"א מוסקבה ב-1977?', array['בתל אביב', 'במוסקבה', 'בווירטון שבבלגיה', 'בבלגרד'], 2, 'לברית המועצות לא היו יחסים דיפלומטיים עם ישראל, ולכן המשחק הועבר למגרש ניטרלי; התוצאה הייתה 79:91.', true, 'ynet, walla ספורט – 1977 וירטון'),
  ('israel_league', 'hard', 'מול איזו קבוצה ניצחה מכבי תל אביב בגמר אליפות אירופה הראשון שלה ב-1977?', array['ורזה האיטלקית', 'ריאל מדריד', 'צסק"א מוסקבה', 'בולוניה'], 0, 'הגמר נערך בבלגרד והסתיים 77:78 — הפרש של נקודה אחת בלבד.', true, 'ויקיפדיה – גביע אירופה לאלופות 1976/77'),
  ('israel_league', 'medium', 'בגמר היורוליג של 2004 רשמה מכבי תל אביב אחד הניצחונות הגדולים בהיסטוריה של המפעל. מה הייתה התוצאה?', array['74:118', '70:90', '80:100', '88:95'], 0, 'הפרש של 44 נקודות — השיא בגמר יורוליג מאז 1958, וגם שיא הנקודות במשחק גמר.', true, 'EuroLeague, ויקיפדיה – פיינל פור 2004'),
  ('israel_league', 'easy', 'מי אימן את מכבי תל אביב בזכייה ביורוליג ב-2014?', array['דויד בלאט', 'פיני גרשון', 'צבי שרף', 'גיא גודס'], 0, 'הגמר מול ריאל מדריד במילאנו הוכרע בהארכה 86:98 — הגמר הראשון שהוכרע בהארכה מאז 1969.', true, 'ויקיפדיה – פיינל פור יורוליג 2014'),
  ('israel_league', 'medium', 'איזו קבוצה ישראלית זכתה בגביע יול"ב (יורוקאפ) ב-2004?', array['הפועל ירושלים', 'הפועל תל אביב', 'מכבי תל אביב', 'הפועל גליל עליון'], 0, 'זו הייתה הזכייה האירופית הראשונה של קבוצה ישראלית שאינה מכבי תל אביב — 72:83 על ריאל מדריד.', true, 'ויקיפדיה – גביע יול"ב 2003/04'),
  ('israel_league', 'easy', 'איזו קבוצה ישראלית זכתה ביורוקאפ בעונת 2024/25?', array['הפועל תל אביב', 'הפועל ירושלים', 'הפועל חולון', 'מכבי ראשון לציון'], 0, 'הפועל גברה בגמר על גראן קנאריה הספרדית והבטיחה לעצמה כרטיס כניסה ליורוליג.', true, 'EuroLeague Basketball, Times of Israel'),
  ('israel_league', 'medium', 'מי המאמן הישראלי היחיד שזכה בשלוש אליפויות אירופה?', array['פיני גרשון', 'דויד בלאט', 'צבי שרף', 'אריק שיבק'], 0, 'גרשון זכה עם מכבי תל אביב ב-2001, 2004 ו-2005, ובסך הכול לקח שמונה אליפויות ישראל.', true, 'ויקיפדיה – פיני גרשון'),
  ('israel_league', 'medium', 'מי מלך הקלעים של כל הזמנים בליגה הבכירה בכדורסל בישראל?', array['דורון ג''מצ''י', 'מיקי ברקוביץ''', 'טל ברודי', 'עודד קטש'], 0, 'ג''מצ''י קלע יותר מ-9,500 נקודות לאורך יותר מ-20 עונות בליגה.', true, 'basket.co.il – קלעי כל הזמנים'),
  ('israel_league', 'hard', 'מי נמצא במקום השני בטבלת קלעי כל הזמנים של הליגה הישראלית?', array['מיקי ברקוביץ''', 'ברד ליף', 'חיים בוכבינדר', 'עודד קטש'], 0, 'ברקוביץ'' הוא גם מלך הקלעים של מכבי תל אביב במפעלים האירופיים, וזכה בפרס ישראל.', true, 'basket.co.il – קלעי כל הזמנים, ויקיפדיה'),
  ('israel_league', 'easy', 'מי היה הישראלי הראשון ששיחק ב-NBA?', array['עומרי כספי', 'דני אבדיה', 'גל מקל', 'עודד קטש'], 0, 'כספי נבחר במקום ה-23 בדראפט 2009 על ידי סקרמנטו קינגס, והיה גם הישראלי הראשון שנבחר בסיבוב הראשון.', true, 'ויקיפדיה – עומרי כספי, JTA'),
  ('israel_league', 'medium', 'איזה שיא קבע דני אבדיה כשזכה בתואר שחקן העונה (MVP) של הליגה הישראלית?', array['הזוכה הצעיר ביותר בהיסטוריה', 'הזוכה הראשון שאינו ישראלי', 'הזוכה עם הכי הרבה נקודות בעונה', 'הזוכה הראשון מקבוצה שירדה ליגה'], 0, 'אבדיה נבחר במקום התשיעי בדראפט 2020 על ידי וושינגטון וויזארדס.', true, 'ויקיפדיה – דני אבדיה'),
