  ('maccabi_europe', 'easy', 'מי אימן את מכבי תל אביב בשתי זכיות היורוליג הרצופות ב-2004 וב-2005?', array['צביקה שרף', 'פיני גרשון', 'דיוויד בלאט', 'שרון דרוקר'], 1, 'גרשון לקח עם מכבי גם את הסופרליג ב-2001, ונבחר למאמן השנה של היורוליג בעונת 2004/05.', true, 'ויקיפדיה, ערך Pini Gershon'),
  ('maccabi_europe', 'easy', 'באיזו עיר נערך הפייבר פור של 2004, שבו הוכתרה מכבי לאלופת אירופה?', array['מוסקבה', 'תל אביב', 'אתונה', 'פראג'], 1, 'מכבי הפכה לאחת הקבוצות הבודדות שהוכתרו על הפרקט הביתי שלהן — בהיכל יד אליהו.', true, 'ויקיפדיה, 2004 Euroleague Final Four'),
