  ('maccabi_europe', 'hard', 'באיזו עיר נערך גמר גביע אירופה של 1977?', array['בלגרד', 'מדריד', 'פריז', 'מילאנו'], 0, 'המשחק נערך באולם "פיוניר", וג''ים בוטרייט של מכבי הוכתר כמלך הקלעים של אותו גמר.', true, 'ויקיפדיה, 1976–77 FIBA European Champions Cup'),
  ('maccabi_europe', 'hard', 'איזו קבוצה איטלקית ניצחה את מכבי תל אביב בשני גמרי גביע אירופה רצופים, ב-1987 וב-1988?', array['טרייסר מילאנו', 'סקוויב קנטו', 'וירטוס בולוניה', 'ורזה'], 0, 'קנטו הביסה את מכבי בגמר 1982, כך שקבוצות איטלקיות עצרו אותה שלוש פעמים בשנות ה-80.', true, 'ויקיפדיה, Maccabi Tel Aviv B.C. in international competitions'),
  ('maccabi_europe', 'hard', 'מול מי הפסידה מכבי תל אביב את גמר גביע אירופה של 1989 במינכן?', array['יוגופלסטיקה ספליט', 'צרוונה זבזדה בלגרד', 'פרטיזן בלגרד', 'צסק"א מוסקבה'], 0, 'יוגופלסטיקה, עם טוני קוקוץ'' ודינו ראג''ה, פתחה באותו ערב רצף של שלוש זכיות אירופיות רצופות.', true, 'ויקיפדיה, 1988–89 FIBA European Champions Cup'),
  ('maccabi_europe', 'hard', 'בשנת 2001 זכתה מכבי בתואר אירופי בתחרות שלא נקראה "יורוליג". איך היא נקראה?', array['סופרליג', 'גביע קוראץ''', 'גביע רונקטי', 'יורוקאפ'], 0, 'באותה עונה התפצל הכדורסל האירופי לשתי תחרויות בכירות יריבות, ואחריה הן אוחדו לתחרות אחת.', true, 'ויקיפדיה, 2000–01 FIBA SuproLeague'),
  ('maccabi_europe', 'hard', 'מי נבחר ל-MVP של הפייבר פור 2001 בפריז?', array['אריאל מקדונלד', 'נייט האפמן', 'עודד קטש', 'אנתוני פארקר'], 0, 'מכבי ניצחה בגמר את פנאתינייקוס 67:81 — בדיוק שנה אחרי שהפסידה לה בגמר של 2000.', true, 'ויקיפדיה, 2001 FIBA SuproLeague Final Four'),
  ('maccabi_europe', 'hard', 'את מי ניצחה מכבי תל אביב בגמר היורוליג של 2005 במוסקבה?', array['טאו ויטוריה', 'צסק"א מוסקבה', 'פנאתינייקוס', 'ברצלונה'], 0, 'הניצחון 78:90 הפך את מכבי לקבוצה הראשונה שזכתה פעמיים ברציפות מאז ספליט ב-1991.', true, 'ויקיפדיה, 2005 Euroleague Final Four'),
  ('maccabi_europe', 'hard', 'מאיזו מדינה הגיע הסנטר ניקולה וויצ''יץ'', מעמודי התווך של מכבי בזכיות 2004 ו-2005?', array['קרואטיה', 'סרביה', 'סלובניה', 'בוסניה'], 0, 'וויצ''יץ'' היה הראשון בעידן המודרני של היורוליג שרשם דאבל־טריפל — והוא עשה זאת פעמיים.', true, 'ויקיפדיה + Eurohoops, ערך Nikola Vujčić'),
  ('maccabi_europe', 'hard', 'מי נבחר ל-MVP של הפייבר פור 2006 בפראג, שבו הפסידה מכבי בגמר?', array['תיאודורוס פפאלוקאס', 'ג''יי אר הולדן', 'טרייג''ן לנגדון', 'דימיטריס דיאמנטידיס'], 0, 'צסק"א ניצחה 69:73 ולקחה את תוארה האירופי הראשון מזה 35 שנה.', true, 'ויקיפדיה + EuroLeague.net, 2006 Final Four'),
  ('maccabi_europe', 'hard', 'איזו קבוצה שברה ב-1993 רצף של 23 אליפויות ישראל רצופות של מכבי תל אביב?', array['הפועל גליל עליון', 'הפועל ירושלים', 'הפועל תל אביב', 'מכבי רמת גן'], 0, 'היא הייתה הקבוצה הראשונה מחוץ לתל אביב שלקחה אליפות בישראל, ואימן אותה פיני גרשון.', true, 'ויקיפדיה, ערכי Hapoel Galil Elyon ו-Pini Gershon'),
  ('maccabi_europe', 'hard', 'בשנת 1994 אירח היכל יד אליהו את הפייבר פור האירופי. מי זכתה בו?', array['חובנטוט בדלונה', 'אולימפיאקוס', 'פנאתינייקוס', 'ברצלונה'], 0, 'חובנטוט ניצחה בגמר את אולימפיאקוס 57:59, ומכבי כלל לא העפילה לארבע האחרונות באותה שנה.', true, 'ויקיפדיה, 1994 FIBA European League Final Four'),
  ('israel_national', 'easy', 'באיזו אליפות אירופה זכתה נבחרת ישראל הבוגרת במדליית כסף — ההישג הגדול בתולדותיה?', array['1979 באיטליה', '1977 בבלגיה', '1981 בצ''כוסלובקיה', '1985 בגרמניה'], 0, 'בדרך למדליה הפילה ישראל את יוגוסלביה, אלופת אירופה והעולם המכהנת, בנקודה אחת בלבד (77-76).', true, 'ויקיפדיה – יורובאסקט 1979'),
  ('israel_national', 'easy', 'מול מי הפסידה נבחרת ישראל בגמר אליפות אירופה 1979?', array['ברית המועצות', 'יוגוסלביה', 'איטליה', 'ספרד'], 0, 'ברית המועצות ניצחה בגמר 98-76, ויוגוסלביה לקחה את הארד.', true, 'ויקיפדיה – יורובאסקט 1979'),
  ('israel_national', 'medium', 'מי אימן את נבחרת ישראל למדליית הכסף באליפות אירופה 1979?', array['ראלף קליין', 'פיני גרשון', 'צבי שרף', 'אריק שיבק'], 0, 'קליין, שכונה «מר בסקטבול», זכה בפרס ישראל בתחום הספורט ב-2006.', true, 'ויקיפדיה – ראלף קליין'),
  ('israel_national', 'easy', 'כמה פעמים זכתה ישראל בתואר אלופת אירופה בכדורסל עד גיל 20 (U20)?', array['פעמיים', 'פעם אחת', 'שלוש פעמים', 'מעולם לא'], 0, 'שני התארים הגיעו בשנים רצופות — 2018 בגרמניה ו-2019 בתל אביב.', true, 'FIBA – U20 European Championship'),
  ('israel_national', 'medium', 'את מי ניצחה ישראל בגמר אליפות אירופה U20 של 2018?', array['קרואטיה', 'ספרד', 'יוון', 'ליטא'], 0, 'הניצחון 80-66 בחמניץ שבגרמניה העניק לכדורסל הישראלי את תואר אירופה הראשון בתולדותיו.', true, 'FIBA.basketball'),
  ('israel_national', 'medium', 'מי נבחר לשחקן המצטיין של אליפות אירופה U20 בשנת 2018?', array['יובל זוסמן', 'דני אבדיה', 'ים מדר', 'תמיר בלאט'], 0, 'לצידו נבחר לחמישייה המצטיינת דני אבדיה, שהיה אז בן 17 והשחקן הצעיר בכל הטורניר.', true, 'FIBA.basketball'),
  ('israel_national', 'easy', 'היכן נערכה אליפות אירופה U20 של 2019, שבה ישראל הגנה על התואר?', array['תל אביב', 'ירושלים', 'אתונה', 'חמניץ'], 0, 'הגמר נערך באולם מלא עד אפס מקום, ודני אבדיה נבחר לשחקן המצטיין של הטורניר.', true, 'ויקיפדיה – 2019 FIBA U20'),
  ('israel_national', 'medium', 'את מי ניצחה ישראל בגמר אליפות אירופה U20 של 2019?', array['ספרד', 'צרפת', 'ליטא', 'סרביה'], 0, 'ישראל, סרביה וצרפת הן הנבחרות היחידות שזכו פעמיים ברצף בתואר ה-U20.', true, 'ויקיפדיה – 2019 FIBA U20'),
  ('israel_national', 'hard', 'מי הוביל את אליפות אירופה U20 של 2019 בממוצע אסיסטים?', array['ים מדר', 'דני אבדיה', 'תמיר בלאט', 'רפי מנקו'], 0, 'הוא רשם 7.7 אסיסטים ו-15.9 נקודות בממוצע, ובדראפט 2020 נבחר על ידי בוסטון סלטיקס.', true, 'ויקיפדיה – ים מדר'),
  ('israel_national', 'medium', 'מי אימן את נבחרת ישראל U20 לשני תארי אירופה, ב-2018 וב-2019?', array['אריאל בית הלחמי', 'עודד קטש', 'גיא גודס', 'ארז אדלשטיין'], 0, 'ב-2023 הוא מונה למאמן הנבחרת הבוגרת, ואיתה הפתיע את צרפת ביורובאסקט 2025.', true, 'ויקיפדיה – אריאל בית הלחמי'),
  ('israel_national', 'easy', 'מי היה השחקן הישראלי הראשון ששיחק ב-NBA?', array['עומרי כספי', 'דני אבדיה', 'ים מדר', 'דורון שפר'], 0, 'כספי נבחר במקום ה-23 בדראפט 2009 והיה גם הישראלי הראשון שנבחר אי פעם בסיבוב הראשון.', true, 'JTA / ויקיפדיה – עומרי כספי'),
  ('israel_national', 'easy', 'באיזה מקום בדראפט 2020 נבחר דני אבדיה על ידי וושינגטון וויזארדס?', array['תשיעי', 'שביעי', 'שלושה־עשר', 'עשרים ושלושה'], 0, 'זו הבחירה הגבוהה ביותר אי פעם של שחקן ישראלי בדראפט ה-NBA.', true, 'NBA.com – Wizards'),
  ('israel_national', 'hard', 'איזה שחקן ישראלי נבחר בדראפט 1996 על ידי לוס אנג''לס קליפרס, אך בחר לחתום במכבי תל אביב?', array['דורון שפר', 'עומרי כספי', 'נדב הנפלד', 'דורון ג''מצ''י'], 0, 'שפר הוא השחקן היחיד בתולדות אוניברסיטת יוקונ שרשם 1,000 נקודות ו-500 אסיסטים בשלוש עונות.', true, 'Basketball-Reference / ויקיפדיה'),
  ('israel_national', 'hard', 'איזו קבוצת NBA בחרה בטל ברודי בדראפט 1965, לפני שבחר לעבור לישראל?', array['בולטימור בולטס', 'בוסטון סלטיקס', 'ניו יורק ניקס', 'פילדלפיה 76'], 0, 'ברודי הגיע לישראל למכביה של 1965, נשאר לשחק במכבי תל אביב, והפך לאחד הסמלים הגדולים של הכדורסל הישראלי.', true, 'Basketball-Reference – Tal Brody'),
  ('israel_national', 'easy', 'את איזו נבחרת גדולה הפתיעה ישראל בשלב הבתים של יורובאסקט 2025?', array['צרפת', 'סרביה', 'ספרד', 'גרמניה'], 0, 'ישראל ניצחה 82-69 — הניצחון הראשון שלה על צרפת מאז 1997 — ואבדיה סיים עם 23 נקודות, 8 ריבאונדים ו-5 חטיפות.', true, 'FIBA EuroBasket 2025'),
  ('israel_national', 'easy', 'מול מי נעצרה דרכה של נבחרת ישראל בשמינית הגמר של יורובאסקט 2025?', array['יוון', 'טורקיה', 'סלובניה', 'פולין'], 0, 'יאניס אנטטוקומפו קלע באותו משחק 37 נקודות והוביל את יוון לניצחון 84-79.', true, 'FIBA EuroBasket 2025'),
  ('israel_national', 'hard', 'כמה נקודות בממוצע למשחק קלע דני אבדיה ביורובאסקט 2025?', array['24', '18', '29', '15'], 0, 'הוא הוסיף 6.8 ריבאונדים בממוצע ונבחר לחמישייה המצטיינת השנייה של הטורניר.', true, 'FIBA / Blazer''s Edge'),
  ('israel_national', 'hard', 'באילו משחקים אולימפיים השתתפה נבחרת הכדורסל של ישראל — הפעם היחידה בהיסטוריה?', array['הלסינקי 1952', 'רומא 1960', 'מינכן 1972', 'מוסקבה 1980'], 0, 'שם נערך גם המשחק הבינלאומי הראשון בתולדות הנבחרת — הפסד 57-47 לפיליפינים.', true, 'ויקיפדיה – נבחרת ישראל בכדורסל'),
  ('israel_national', 'hard', 'ישראל זכתה פעמיים בזהב בכדורסל במשחקים האסייתיים. באילו שנים?', array['1966 ו-1974', '1962 ו-1970', '1970 ו-1978', '1958 ו-1966'], 0, 'ב-1974 בטהרן גברה ישראל בגמר על דרום קוריאה; אלה היו המשחקים האסייתיים האחרונים שלה, ומאז היא מתחרה במסגרת אירופה.', true, 'ויקיפדיה – Basketball at the Asian Games'),
  ('israel_national', 'medium', 'מהו ההישג הטוב ביותר של נבחרת ישראל הבוגרת בגביע העולם (מונדיאל)?', array['מקום שביעי ב-1986', 'מקום רביעי ב-1954', 'מקום חמישי ב-1970', 'מעולם לא השתתפה'], 0, 'ישראל השתתפה במונדיאל פעמיים בלבד — 1954, שם סיימה שמינית, ו-1986 בספרד.', true, 'ויקיפדיה – 1986 FIBA World Championship'),
  ('israel_national', 'easy', 'איזו עיר בישראל אירחה בית שלם ביורובאסקט 2017?', array['תל אביב', 'ירושלים', 'חיפה', 'באר שבע'], 0, 'ארבע ערים אירחו את הבתים — הלסינקי, תל אביב, קלוז'' וקושטא — ושלב הנוקאאוט כולו נערך בקושטא.', true, 'FIBA / ויקיפדיה – EuroBasket 2017'),
  ('israel_national', 'medium', 'מי היה הישראלי הראשון שנכנס להיכל התהילה של פיב"א?', array['מיקי ברקוביץ''', 'טל ברודי', 'ראלף קליין', 'עומרי כספי'], 0, 'הוא נכנס במחזור 2017, יחד עם שאקיל אוניל וטוני קוקוץ''.', true, 'FIBA.basketball – 2017 Hall of Fame'),
  ('israel_national', 'hard', 'באיזו אליפות אירופה לנשים רשמה נבחרת ישראל הבוגרת את הישגה הטוב ביותר, מקום שמיני?', array['1991, כשאירחה', '2003 ביוון', '2007 באיטליה', '2023, כשאירחה'], 0, 'ב-2023 ישראל אירחה שוב, הפעם יחד עם סלובניה, וסיימה במקום ה-16.', true, 'ויקיפדיה – נבחרת הנשים של ישראל'),
  ('israel_national', 'medium', 'איזו נבחרת נשים ישראלית זכתה ב-2026 במדליה הראשונה אי פעם של כדורסל הנשים הישראלי?', array['נבחרת העד גיל 20', 'הנבחרת הבוגרת', 'נבחרת העד גיל 16', 'נבחרת ה-3 על 3'], 0, 'בגמר בליטא הפסידה ישראל לצרפת 79-66, כשגל רביב קלעה 29 נקודות ונבחרה לחמישייה המצטיינת.', true, 'JNS / ג''רוזלם פוסט'),
  ('israel_national', 'medium', 'מה עשתה נבחרת ישראל עד גיל 19 בהופעת הבכורה שלה במונדיאל U19 בשנת 2025?', array['סיימה במקום השביעי', 'הודחה בשלב הבתים', 'זכתה במדליית ארד', 'סיימה במקום האחרון'], 0, 'בהופעה ראשונה אי פעם ישראל העפילה עד רבע הגמר, וסגרה בניצחון 79-68 על שווייץ המארחת.', true, 'FIBA U19 World Cup 2025'),
  ('israel_national', 'hard', 'באיזו אליפות אירופה U20 הפסידה ישראל בגמר לצרפת אחרי הארכה?', array['2023', '2017', '2022', '2025'], 0, 'זו הייתה מדליית הכסף הרביעית של ישראל ב-U20, אחרי 2000, 2004 ו-2017.', true, 'FIBA – U20 European Championship 2023'),
  ('israel_national', 'hard', 'מול מי הפסידה ישראל בגמר אליפות אירופה U20 של 2017?', array['יוון', 'ספרד', 'קרואטיה', 'צרפת'], 0, 'הגמר, שנערך באי כרתים, הסתיים 65-56 — ושנה לאחר מכן ישראל חזרה ולקחה את התואר.', true, 'FIBA – U20 European Championship 2017'),
  ('israel_national', 'hard', 'איזה שחקן נבחרת ישראל שבר בעונת 1989/90 את שיא ה-NCAA לחטיפות של שחקן שנה ראשונה?', array['נדב הנפלד', 'דורון שפר', 'עודד קטש', 'דורון ג''מצ''י'], 0, 'הוא רשם 138 חטיפות בעונה אחת ביוקונ, נבחר לשחקן השנה הראשונה של ה-Big East, ואז חזר לשחק בישראל.', true, 'UConn Huskies / ויקיפדיה – נדב הנפלד'),
  ('nba_history', 'easy', 'בכמה אליפויות NBA זכה מייקל ג''ורדן עם שיקגו בולס?', array['4', '5', '6', '7'], 2, 'ג''ורדן ניצח בכל שישה הגמרים שבהם שיחק, ומעולם לא נאלץ לשחק משחק שביעי בגמר.', true, 'NBA.com – Bulls championships'),
  ('nba_history', 'easy', 'מי מחזיק בשיא הנקודות בקריירה בהיסטוריה של ה-NBA?', array['קארים עבדול-ג''באר', 'לברון ג''יימס', 'מייקל ג''ורדן', 'קרל מאלון'], 1, 'לברון עקף את קארים בפברואר 2023, אחרי ששיא הנקודות היה בידי קארים במשך כמעט 39 שנה.', true, 'NBA.com scoring leaders'),
  ('nba_history', 'easy', 'כמה נקודות קלע וילט צ''מברלין במשחק אחד — השיא של כל הזמנים?', array['81', '92', '100', '73'], 2, 'המשחק ההוא מ-1962 נערך בעיירה הרשי שבפנסילבניה ומעולם לא צולם — נשמרה רק הקלטת רדיו.', true, 'NBA.com history 1961-62'),
  ('nba_history', 'medium', 'מול איזו קבוצה קלע וילט צ''מברלין 100 נקודות?', array['בוסטון סלטיקס', 'ניו יורק ניקס', 'סירקיוז נשיונלס', 'לוס אנג''לס לייקרס'], 1, 'באותו ערב הוא קלע 28 מתוך 32 זריקות עונשין — למרות שקליעות העונשין היו החולשה הגדולה שלו.', true, 'Wikipedia 1961–62 Philadelphia Warriors'),
  ('nba_history', 'easy', 'בכמה אליפויות NBA זכה ביל ראסל?', array['8', '9', '11', '13'], 2, 'הוא עשה זאת ב-13 עונות בלבד, ובשתיים מהן הוא גם שימש כמאמן הראשי של הסלטיקס.', true, 'Hoophall – Bill Russell'),
  ('nba_history', 'medium', 'איזה מספר חולצה הקפיאה כל ליגת ה-NBA לכבוד ביל ראסל בשנת 2022?', array['6', '11', '32', '33'], 0, 'זו הייתה הפעם הראשונה בהיסטוריה שמספר הוקפא בכל 30 הקבוצות של הליגה בבת אחת.', true, 'NBA.com – Russell No. 6 retired league-wide'),
  ('nba_history', 'easy', 'איזו קבוצה זכתה בשמונה אליפויות NBA רצופות בין 1959 ל-1966?', array['לוס אנג''לס לייקרס', 'בוסטון סלטיקס', 'פילדלפיה וריורס', 'ניו יורק ניקס'], 1, 'זהו רצף האליפויות הארוך ביותר בהיסטוריה של הספורט המקצועני בצפון אמריקה, בכל ענף.', true, 'NBA.com list of champions'),
  ('nba_history', 'easy', 'מה שמה של הזריקה המפורסמת שסימנה את קארים עבדול-ג''באר?', array['פיידאווי', 'סקייהוק', 'דרים־שייק', 'יורופסטפ'], 1, 'כמעט אף מגן לא הצליח לחסום אותה, והיא הביאה אותו ל-38,387 נקודות קריירה.', true, 'NBA.com legends profile'),
  ('nba_history', 'medium', 'עם איזו קבוצה זכה קארים עבדול-ג''באר באליפות הראשונה שלו, ב-1971?', array['לוס אנג''לס לייקרס', 'מילווקי באקס', 'ניו יורק ניקס', 'פילדלפיה 76'], 1, 'זו הייתה עונתו השנייה בליגה, ולמילווקי לקח עוד 50 שנה — עד 2021 — לזכות באליפות נוספת.', true, 'NBA.com champions list'),
  ('nba_history', 'hard', 'מי היחיד בהיסטוריה שנבחר ל-MVP של גמר ה-NBA למרות שקבוצתו הפסידה בסדרה?', array['אלג''ין ביילור', 'ג''רי ווסט', 'וילט צ''מברלין', 'אוסקר רוברטסון'], 1, 'זה קרה ב-1969 — השנה הראשונה שבה התואר הוענק בכלל, והלייקרס הפסידו 4-3 לסלטיקס.', true, 'Wikipedia 1969 NBA Finals'),
  ('nba_history', 'medium', 'דמותו של איזה שחקן שימשה כהשראה לצללית שבלוגו של ה-NBA?', array['ג''רי ווסט', 'אוסקר רוברטסון', 'ביל ראסל', 'ג''ון האבליצ''ק'], 0, 'המעצב אלן סיגל אישר זאת ב-2010, אבל הליגה עצמה מעולם לא הודתה בכך באופן רשמי.', true, 'NBA.com Q&A with Alan Siegel'),
  ('nba_history', 'easy', 'כמה נקודות קלע קובי ברייאנט במשחק המפורסם שלו מול טורונטו ראפטורס ב-2006?', array['71', '78', '81', '89'], 2, 'זו התוצאה השנייה בגובהה אי פעם במשחק NBA אחד, אחרי ה-100 של וילט צ''מברלין.', true, 'NBA.com single-game scoring records'),
  ('nba_history', 'easy', 'אילו שני מספרי חולצה הקפיאו הלייקרס לכבוד קובי ברייאנט?', array['8 ו-24', '24 ו-33', '8 ו-32', '13 ו-24'], 0, 'קובי לבש 8 בעשור הראשון בקריירה ו-24 בעשור השני — ושתי החולצות תלויות זו לצד זו באולם.', true, 'NBA.com Lakers retired numbers'),
  ('nba_history', 'hard', 'איזו קבוצה בחרה את קובי ברייאנט בדראפט 1996 לפני שהעבירה אותו ללייקרס?', array['ניו ג''רזי נטס', 'שארלוט הורנטס', 'מילווקי באקס', 'פילדלפיה 76'], 1, 'התמורה הייתה הסנטר ולאדה דיבאץ'' — מהלך שפינה ללייקרס מקום להחתים את שאקיל אוניל.', true, 'Lakers Nation – Divac trade'),
  ('nba_history', 'medium', 'עם איזו קבוצה זכה שאקיל אוניל באליפות הרביעית שלו, ב-2006?', array['מיאמי היט', 'פיניקס סאנס', 'בוסטון סלטיקס', 'קליבלנד קאבלירס'], 0, 'מיאמי הפסידה את שני המשחקים הראשונים בסדרה ואז ניצחה ארבעה ברצף, עם דוויין וייד כ-MVP הגמר.', true, 'NBA.com 2006 Finals'),
  ('nba_history', 'easy', 'כמה אליפויות רצופות זכו הלייקרס של קובי ושאק בתחילת שנות ה-2000?', array['שתיים', 'שלוש', 'ארבע', 'חמש'], 1, '2000, 2001 ו-2002 — ושאק נבחר ל-MVP הגמר בכל שלוש הפעמים, הישג נדיר ביותר.', true, 'NBA.com champions list'),
  ('nba_history', 'medium', 'מי היה המאמן הראשי השחור הראשון בהיסטוריה של ה-NBA?', array['לני ווילקנס', 'ק.ס. ג''ונס', 'ביל ראסל', 'ארל לויד'], 2, 'הוא מונה ב-1966 כשחקן־מאמן, והוביל את בוסטון לשתי אליפויות בזמן שגם שיחק וגם אימן.', true, 'History.com – Russell first Black NBA coach'),
  ('nba_history', 'hard', 'מי זכה בהכי הרבה תארי MVP של העונה הסדירה בהיסטוריית ה-NBA?', array['מייקל ג''ורדן', 'ביל ראסל', 'קארים עבדול-ג''באר', 'לברון ג''יימס'], 2, 'שישה תארים — לג''ורדן ולראסל יש חמישה כל אחד, וגם הפרס עצמו נקרא היום על שם ג''ורדן.', true, 'Basketball-Reference MVP list'),
  ('nba_history', 'easy', 'איזו קבוצה שברה את שיא 72 הניצחונות בעונה של הבולס מ-1996?', array['גולדן סטייט ווריורס', 'סן אנטוניו ספרס', 'מיאמי היט', 'לוס אנג''לס לייקרס'], 0, 'ווריורס סיימו 73-9 בעונת 2015/16 — ובכל זאת הפסידו באותה שנה בגמר לקליבלנד.', true, 'NBA.com 2015-16 season'),
  ('nba_history', 'easy', 'מאיזה פיגור בסדרה התאוששו קליבלנד קאבלירס כדי לזכות בגמר 2016?', array['0-2', '1-3', '0-3', '2-3'], 1, 'אף קבוצה לא חזרה מפיגור כזה בגמר NBA לפני כן, ואף אחת לא חזרה על כך מאז.', true, 'NBA.com 2016 Finals'),
  ('nba_history', 'hard', 'על מי חסם לברון ג''יימס את החסימה המפורסמת במשחק השביעי של גמר 2016?', array['סטפן קרי', 'קליי תומפסון', 'אנדרה איגודאלה', 'דריימונד גרין'], 2, 'החסימה הגיעה בשוויון 89-89 בדקות האחרונות, ומיד אחריה קיירי אירווינג קלע את השלשה המכריעה.', true, 'NBA.com 2016 Finals Game 7'),
  ('nba_history', 'medium', 'מי קלע את שלשת הפינה שהצילה את מיאמי במשחק השישי של גמר 2013?', array['ריי אלן', 'דוויין וייד', 'מריו צ''למרס', 'קריס בוש'], 0, 'הוא השווה את התוצאה 5.2 שניות לסיום, מיאמי ניצחה בהארכה ולקחה את האליפות במשחק שביעי.', true, 'NBA.com 2013 Finals'),
  ('nba_history', 'easy', 'לאיזו קבוצה עבר לברון ג''יימס ב-2010 במהלך שכונה "ההחלטה"?', array['שיקגו בולס', 'מיאמי היט', 'ניו יורק ניקס', 'לוס אנג''לס קליפרס'], 1, 'הוא זכה שם בשתי אליפויות, ב-2012 וב-2013, לפני שחזר לקליבלנד ב-2014.', true, 'NBA.com Heat history'),
  ('nba_history', 'medium', 'מי הוביל את דאלאס מאבריקס לאליפות 2011 מול מיאמי?', array['ג''ייסון קיד', 'סטיב נאש', 'דירק נוביצקי', 'טייסון צ''נדלר'], 2, 'נוביצקי נבחר ל-MVP הגמר, וזו נותרה האליפות היחידה בהיסטוריה של מאבריקס.', true, 'NBA.com 2011 Finals'),
  ('nba_history', 'hard', 'איזו קבוצה בחרה את דירק נוביצקי בדראפט 1998 לפני שהחליפה אותו לדאלאס?', array['דנבר נאגטס', 'מילווקי באקס', 'פיניקס סאנס', 'ניו ג''רזי נטס'], 1, 'מילווקי קיבלה בתמורה את רוברט "טרקטור" טריילור, שנעלם מהליגה אחרי שבע עונות בלבד.', true, 'Freezing Cold Takes / GiveMeSport – 1998 draft trade'),
  ('nba_history', 'hard', 'מי מחזיק בשיא ה-NBA של 30 אסיסטים במשחק אחד?', array['ג''ון סטוקטון', 'מג''יק ג''ונסון', 'סקוט סקיילס', 'אייזיה תומאס'], 2, 'סקיילס עשה זאת ב-1990 עם אורלנדו מג''יק — יותר מכפול מכל האסיסטים של קבוצת דנבר באותו ערב.', true, 'NBA.com – most assists in a game'),
  ('nba_history', 'medium', 'מי מחזיק בשיא האסיסטים בקריירה בהיסטוריית ה-NBA?', array['מג''יק ג''ונסון', 'ג''ון סטוקטון', 'כריס פול', 'ג''ייסון קיד'], 1, '15,806 אסיסטים — יותר מ-3,000 מעל השני ברשימה, פער שנחשב כמעט בלתי ניתן לסגירה.', true, 'Basketball-Reference career assists'),
  ('nba_history', 'medium', 'מי מחזיק בשיא הריבאונדים בקריירה בהיסטוריית ה-NBA?', array['ביל ראסל', 'וילט צ''מברלין', 'קארים עבדול-ג''באר', 'מוזס מאלון'], 1, '23,924 ריבאונדים; ב-1960 הוא גם לקח 55 ריבאונדים במשחק אחד — שיא שעומד עד היום.', true, 'History.com – Wilt 55 rebounds'),
  ('nba_history', 'hard', 'מי מחזיק בשיא החסימות בקריירה מאז שהחלו לתעד את הנתון?', array['דיקמבה מוטומבו', 'מארק איטון', 'האקים אולאג''ואן', 'קארים עבדול-ג''באר'], 2, 'ב-1994 הוא לקח באותה עונה MVP, מגן השנה ו-MVP הגמר — היחיד בהיסטוריה שעשה זאת.', true, 'NBA.com legends profile Hakeem'),
  ('nba_history', 'hard', 'כמה נקודות קלע אלג''ין ביילור ב-1962 — שיא שעדיין עומד למשחק גמר בודד?', array['55', '61', '63', '69'], 1, 'למרות ההופעה הענקית, בוסטון לקחה את הסדרה ההיא 4-3 והשיא שרד יותר משישים שנה.', true, 'Guinness World Records / NBA.com'),
  ('nba_history', 'easy', 'לאיזו קבוצה יש הכי הרבה אליפויות NBA בהיסטוריה?', array['בוסטון סלטיקס', 'לוס אנג''לס לייקרס', 'גולדן סטייט ווריורס', 'שיקגו בולס'], 0, '18 אליפויות מול 17 של הלייקרס — הפער נפתח כשבוסטון זכתה ב-2024 ושברה את השוויון.', true, 'NBA.com list of champions'),
  ('nba_history', 'easy', 'מול איזו קבוצה שיחקו הסלטיקס של לארי בירד שלושה גמרי NBA בשנות ה-80?', array['פילדלפיה 76', 'דטרויט פיסטונס', 'לוס אנג''לס לייקרס', 'יוסטון רוקטס'], 2, '1984, 1985 ו-1987 — ובוסטון ניצחה רק את הראשון מביניהם.', true, 'Wikipedia Celtics–Lakers rivalry'),
  ('nba_history', 'medium', 'בכמה אליפויות NBA זכה לארי בירד?', array['שתיים', 'שלוש', 'ארבע', 'חמש'], 1, '1981, 1984 ו-1986 — וכל הקריירה שלו, 13 עונות, עברה בקבוצה אחת בלבד.', true, 'NBA.com champions list'),
  ('nba_history', 'medium', 'בכמה תחרויות שלשות רצופות ניצח לארי בירד באול-סטאר?', array['שתיים', 'שלוש', 'ארבע', 'חמש'], 1, '1986, 1987 ו-1988 — ולפני אחת מהן הוא נכנס לחדר ההלבשה ושאל את המתחרים מי מגיע למקום השני.', true, 'Wikipedia Three-Point Contest'),
  ('nba_history', 'medium', 'באיזה תואר זכה מג''יק ג''ונסון כבר בעונת הטירונות שלו, ב-1980?', array['MVP של העונה', 'MVP של הגמר', 'מגן השנה', 'מלך הקלעים'], 1, 'במשחק המכריע הוא שיחק סנטר במקום קארים הפצוע וסיים עם 42 נקודות, 15 ריבאונדים ו-7 אסיסטים.', true, 'NBA.com 1980 Finals Game 6'),
  ('nba_history', 'medium', 'מי המאמן עם הכי הרבה אליפויות NBA בהיסטוריה?', array['רד אורבך', 'פאט ריילי', 'פיל ג''קסון', 'גרג פופוביץ'''], 2, '11 אליפויות כמאמן — שש עם הבולס וחמש עם הלייקרס — ועוד שתיים שזכה בהן כשחקן בניקס.', true, 'Britannica / StatMuse coaching titles'),
  ('nba_history', 'medium', 'איזו קבוצה זכתה באליפות ב-1989 וב-1990 וכונתה "הבד בויז"?', array['דטרויט פיסטונס', 'ניו יורק ניקס', 'שיקגו בולס', 'פילדלפיה 76'], 0, 'השיטה הפיזית שלהם לעצירת ג''ורדן קיבלה שם משלה: "חוקי ג''ורדן".', true, 'NBA.com champions list'),
  ('nba_history', 'easy', 'במה עסק מייקל ג''ורדן בין הפרישה שלו ב-1993 לחזרה ב-1995?', array['בייסבול מקצועני', 'פוטבול אמריקאי', 'גולף מקצועני', 'אימון קבוצת קולג'''], 0, 'הוא שיחק בליגת המשנה עם בירמינגהאם ברונס, קבוצת החווה של שיקגו וייט סוקס.', true, 'SI – Jordan returns from baseball'),
  ('nba_history', 'hard', 'מי היה השחקן הראשון שקבוצה הקפיאה את מספרו למרות שמעולם לא שיחק בה?', array['ביל ראסל', 'וילט צ''מברלין', 'מייקל ג''ורדן', 'קובי ברייאנט'], 2, 'מיאמי היט הקפיאה את ה-23 שלו ב-2003, ודאלאס עשתה מחווה דומה עם המספר 24 לכבוד קובי ב-2020.', true, 'ESPN / NBA.com Heat retired numbers'),
  ('nba_history', 'hard', 'באיזה דירוג נכנסו יוסטון רוקטס לפלייאוף בדרך לאליפות 1995?', array['ראשון', 'שלישי', 'שישי', 'שמיני'], 2, 'זהו הדירוג הנמוך ביותר שזכה אי פעם באליפות; בדרך הם הפכו פיגור 1-3 מול פיניקס.', true, 'Wikipedia 1995 NBA playoffs'),
  ('nba_history', 'hard', 'כמה קבוצות מליגת ה-ABA הצטרפו ל-NBA במיזוג של 1976?', array['שתיים', 'ארבע', 'שש', 'שמונה'], 1, 'נאגטס, פייסרס, נטס וספרס — ומאותה ליגה ה-NBA ירש גם את הרעיון של קו השלשה.', true, 'History.com – NBA merges with ABA'),
  ('nba_history', 'hard', 'באיזו עונה הונהג קו השלשה ב-NBA?', array['1969/70', '1979/80', '1986/87', '1994/95'], 1, 'זו הייתה במקרה גם עונת הטירונות של מג''יק ג''ונסון ולארי בירד.', true, 'NBA.com rules history'),
  ('nba_history', 'easy', 'כמה שניות היו בשעון הזריקות כשהונהג לראשונה ב-1954?', array['20', '24', '30', '35'], 1, 'דני ביאזון, בעל סירקיוז, חילק 2,880 שניות משחק ב-120 זריקות ממוצעות והגיע בדיוק למספר הזה.', true, 'WBUR / Le Moyne College shot clock history'),
  ('nba_history', 'hard', 'מי קלע את הנקודות הראשונות בהיסטוריה של הליגה, במשחק הפתיחה ב-1946?', array['ג''ורג'' מייקן', 'אוסי שכטמן', 'בוב קאוזי', 'דולף שייס'], 1, 'שכטמן היה שחקן יהודי־אמריקאי, והמשחק נערך בטורונטו בין ההאסקיז לניקרבוקרס מניו יורק.', true, 'History.com – first NBA game 1946'),
  ('nba_history', 'hard', 'איזה דבר מפתיע מעולם לא קרה לוילט צ''מברלין באף אחד ממשחקי הקריירה שלו?', array['הוא מעולם לא הורחק בגלל חמש עבירות', 'הוא מעולם לא החטיא זריקת עונשין', 'הוא מעולם לא ירד לספסל', 'הוא מעולם לא איבד כדור'], 0, 'בכל 1,205 המשחקים שלו הוא ממוצע כשתי עבירות למשחק בלבד — למרות ששיחק בעמדה הפיזית ביותר.', true, 'ESPN Classic / FanSided – Wilt never fouled out'),
