  ('nba_history', 'hard', 'מי מחזיק בממוצע הנקודות הגבוה ביותר למשחק בקריירה בהיסטוריית ה-NBA?', array['וילט צ''מברלין', 'מייקל ג''ורדן', 'קובי ברייאנט', 'לברון ג''יימס'], 1, 'כ-30.1 נקודות בממוצע — פחות מעשירית נקודה מעל וילט צ''מברלין, שנמצא ממש מאחוריו.', true, 'Basketball-Reference – Michael Jordan'),
  ('nba_history', 'medium', 'את מי ניצחו הבולס בגמר ה-NBA הראשון של מייקל ג''ורדן ב-1991?', array['פורטלנד טרייל בלייזרס', 'פיניקס סאנס', 'לוס אנג''לס לייקרס', 'יוטה ג''אז'], 2, 'זו הייתה הסדרה האחרונה של מג''יק ג''ונסון בגמר NBA — סוף עידן במקביל לתחילת עידן אחר.', true, 'NBA.com champions list'),
  ('nba_modern', 'easy', 'איזו קבוצה זכתה באליפות ה-NBA בעונת 2025/26?', array['ניו יורק ניקס', 'סן אנטוניו ספרס', 'אוקלהומה סיטי ת''אנדר', 'בוסטון סלטיקס'], 0, 'זה היה התואר הראשון של הניקס מאז 1973 — המתנה של 53 שנה.', true, 'ויקיפדיה, גמר NBA 2026'),
