  ('nba_modern', 'medium', 'מי נבחר ל-MVP של גמר ה-NBA ב-2026?', array['ג''יילן ברונסון', 'ויקטור ומבניאמה', 'קארל-אנתוני טאונס', 'דילן הארפר'], 0, 'במשחק החמישי והסוגר הוא קלע 45 נקודות בחוץ — שוויון לשיא של מייקל ג''ורדן במשחק סוגר על אדמת היריבה.', true, 'ויקיפדיה, גמר NBA 2026'),
  ('nba_modern', 'hard', 'איזו קבוצה הייתה הראשונה בהיסטוריה שזכתה גם בגביע ה-NBA (טורניר אמצע העונה) וגם באליפות באותה עונה?', array['ניו יורק ניקס', 'לוס אנג''לס לייקרס', 'מילווקי באקס', 'אוקלהומה סיטי ת''אנדר'], 0, 'הניקס ניצחו את הספרס בגמר הגביע בדצמבר 2025 — ואז שוב בגמר האליפות ביוני 2026.', true, 'ויקיפדיה, גביע NBA 2025'),
  ('nba_modern', 'easy', 'מי זכה בתואר MVP של העונה הסדירה ב-2025/26?', array['שיי גילג''וס-אלכסנדר', 'ניקולה יוקיץ''', 'ויקטור ומבניאמה', 'לוקה דונצ''יץ'''], 0, 'זה היה ה-MVP השני שלו ברציפות, והוא ה-14 בהיסטוריה שזוכה בתואר פעמיים ברצף.', true, 'NBA.com, פרסי 2025-26'),
  ('nba_modern', 'easy', 'איזו קבוצה זכתה באליפות ה-NBA בעונת 2024/25?', array['אוקלהומה סיטי ת''אנדר', 'אינדיאנה פייסרס', 'בוסטון סלטיקס', 'דנבר נאגטס'], 0, 'הסדרה הוכרעה במשחק שביעי — הראשון בגמר NBA מאז 2016.', true, 'ויקיפדיה, גמר NBA 2025'),
  ('nba_modern', 'hard', 'מי קלע 83 נקודות במשחק אחד במרץ 2026, השיא השני בגובהו בהיסטוריית ה-NBA?', array['באם אדבאיו', 'לוקה דונצ''יץ''', 'ג''ואל אמביד', 'אנתוני אדוארדס'], 0, 'באותו ערב הוא גם קלע 36 זריקות עונשין — שיא NBA של כל הזמנים למשחק בודד.', true, 'ויקיפדיה + StatMuse'),
  ('nba_modern', 'easy', 'מהו מספר הנקודות הגבוה ביותר שנקלע אי פעם על ידי שחקן אחד במשחק NBA?', array['100', '83', '81', '73'], 0, 'וילט צ''מברלין עשה זאת ב-1962; אחריו ברשימה 83 של באם אדבאיו ב-2026 ו-81 של קובי בראיינט ב-2006.', true, 'ויקיפדיה, שיאי קליעה במשחק בודד'),
  ('nba_modern', 'medium', 'כמה ניצחונות רשמו גולדן סטייט ווריורס בעונה הסדירה 2015/16 — שיא כל הזמנים ב-NBA?', array['73', '72', '70', '67'], 0, 'הם שברו את שיא שיקגו בולס מ-1996 (72 ניצחונות), אבל בסופו של דבר הפסידו בגמר.', true, 'ויקיפדיה, גמר NBA 2016'),
