  ('nba_modern', 'medium', 'בזכייה באליפות 2024 עקפה בוסטון סלטיקס את הלייקרס. לכמה אליפויות הגיעה?', array['18', '17', '16', '20'], 0, 'MVP הסדרה היה דווקא ג''יילן בראון, בזכייתו הראשונה בתואר.', true, 'ויקיפדיה, גמר NBA 2024'),
  ('nba_modern', 'easy', 'איזו קבוצה בחרה את ויקטור ומבניאמה במקום הראשון בדראפט 2023?', array['סן אנטוניו ספרס', 'שרלוט הורנטס', 'יוסטון רוקטס', 'פורטלנד טרייל בלייזרס'], 0, 'הוא הצרפתי הראשון בהיסטוריה שנבחר ראשון בדראפט ה-NBA.', true, 'ויקיפדיה, ויקטור ומבניאמה'),
