  ('nba_modern', 'easy', 'איזו קבוצה בחרה את קופר פלאג במקום הראשון בדראפט 2025?', array['דאלאס מאבריקס', 'סן אנטוניו ספרס', 'פילדלפיה סיקסרס', 'שרלוט הורנטס'], 0, 'בעונת הבכורה שלו הוא נבחר לחדש השנה עם ממוצע של 21 נקודות למשחק.', true, 'ויקיפדיה, דראפט NBA 2025'),
