  ('nba_modern', 'medium', 'כמה נקודות קלע לוקה דונצ''יץ'' בשיא הקריירה שלו, בינואר 2024 מול אטלנטה הוקס?', array['73', '60', '65', '81'], 0, 'זו הייתה ההופעה היעילה ביותר בהיסטוריה של 70 נקודות ומעלה — 25 קליעות מתוך 33 ניסיונות.', true, 'ESPN, ינואר 2024'),
  ('nba_modern', 'easy', 'באיזה מקום נבחר דני אבדיה בדראפט ה-NBA של 2020?', array['תשיעי', 'חמישי', '15', '23'], 0, 'זו הבחירה הגבוהה ביותר אי פעם של ישראלי; עומרי כספי, הישראלי הראשון ששיחק ב-NBA, נבחר ב-2009 במקום ה-23.', true, 'ויקיפדיה, דני אבדיה ועומרי כספי'),
  ('nba_modern', 'hard', 'איזו קבוצה בחרה את הישראלי בן שרף בדראפט 2025?', array['ברוקלין נטס', 'ואשינגטון וויזארדס', 'פורטלנד טרייל בלייזרס', 'סקרמנטו קינגס'], 0, 'שרף נבחר במקום ה-26, אחרי עונה בקבוצת ראטיופארם אולם בליגה הגרמנית.', true, 'ויקיפדיה, דראפט NBA 2025'),
  ('nba_modern', 'hard', 'בכמה תארי שחקן ההגנה של השנה זכה רודי גובר עד תום עונת 2025/26?', array['ארבעה', 'שלושה', 'חמישה', 'שניים'], 0, 'הוא חולק את שיא כל הזמנים עם דיקמבה מוטומבו ובן וואלאס.', true, 'ויקיפדיה, פרס שחקן ההגנה של השנה'),
  ('nba_modern', 'medium', 'אילו מקומות בטבלת כל ועידה משתתפים בטורניר הפליי-אין של ה-NBA?', array['7 עד 10', '8 עד 10', '7 עד 9', '9 עד 12'], 0, 'הפורמט הוצג לראשונה בעונת 2019/20 בבועת אורלנדו, והפך לקבוע בליגה ב-2022.', true, 'ויקיפדיה, טורניר הפליי-אין'),
  ('nba_modern', 'medium', 'איזו קבוצה זכתה בטורניר אמצע העונה הראשון של ה-NBA, בדצמבר 2023?', array['לוס אנג''לס לייקרס', 'אינדיאנה פייסרס', 'מילווקי באקס', 'בוסטון סלטיקס'], 0, 'לברון ג''יימס, בן 38 באותו ערב, נבחר ל-MVP של הטורניר.', true, 'ויקיפדיה, טורניר אמצע העונה 2023'),
  ('nba_modern', 'hard', 'בשנת 2025 סיים גרג פופוביץ'' את תפקידו כמאמן סן אנטוניו ספרס. כמה עונות אימן את הקבוצה?', array['29', '20', '25', '33'], 0, 'פופוביץ'' הוא בעל מספר הניצחונות הרב ביותר בהיסטוריה של מאמני NBA, אחרי שעקף את דון נלסון ב-2022.', true, 'ויקיפדיה, גרג פופוביץ'''),
  ('nba_modern', 'medium', 'מי זכה בתואר MVP של העונה הסדירה בעונת 2022/23?', array['ג''ואל אמביד', 'ניקולה יוקיץ''', 'יאניס אנטטוקומפו', 'ג''ייסון טייטום'], 0, 'אמביד קטע רצף של ארבע עונות שבהן יוקיץ'' ואנטטוקומפו חלקו ביניהם את התואר.', true, 'ויקיפדיה, פרס ה-MVP'),
  ('nba_modern', 'hard', 'מי זכה בתואר MVP של העונה הסדירה בעונת 2017/18?', array['ג''יימס הארדן', 'לברון ג''יימס', 'אנתוני דייויס', 'דיימיאן לילארד'], 0, 'זהו ה-MVP היחיד בקריירה של הארדן, שהיה אז שחקן יוסטון רוקטס.', true, 'ויקיפדיה, פרס ה-MVP'),
  ('nba_modern', 'easy', 'כמה נקודות קלע קובי בראיינט במשחק האחרון בקריירה שלו, באפריל 2016?', array['60', '50', '45', '81'], 0, 'הלייקרס ניצחו באותו ערב את יוטה ג''אז 96:101, בסיום של עונה שבה זכו ב-17 משחקים בלבד.', true, 'ויקיפדיה, עונת 2015-16 של הלייקרס'),
  ('nba_modern', 'hard', 'מי נבחר ראשון בדראפט ה-NBA של 2026?', array['איי-ג''יי דיבנטסה', 'דילן הארפר', 'קופר פלאג', 'וי-ג''יי אדג''קום'], 0, 'ואשינגטון וויזארדס בחרה אותו — הפעם הראשונה שהיא מחזיקה בבחירה הראשונה מאז ג''ון וול ב-2010.', true, 'ויקיפדיה, רשימת נבחרי מקום ראשון בדראפט'),
  ('nba_modern', 'hard', 'מי זכה בתואר החדש של השנה בעונת 2019/20?', array['ג''ה מוראנט', 'זיון וויליאמסון', 'אר-ג''יי בארט', 'קנדריוס טולדזון'], 0, 'מוראנט נבחר במקום השני בדראפט 2019, מיד אחרי זיון וויליאמסון.', true, 'ויקיפדיה, פרס החדש של השנה'),
  ('rules', 'easy', 'כמה דקות נמשך רבע במשחק לפי חוקי פיב״א?', array['8 דקות', '10 דקות', '12 דקות', '15 דקות'], 1, 'משחק פיב״א נמשך 40 דקות נטו, בעוד משחק אן־בי־איי נמשך 48 דקות — 12 דקות לרבע.', true, 'חוקי הכדורסל הרשמיים של פיב״א 2024, סעיף 8.1'),
  ('rules', 'easy', 'לפי חוקי פיב״א, כמה עבירות אישיות גורמות לשחקן לצאת מהמשחק?', array['ארבע', 'חמש', 'שש', 'שבע'], 1, 'שחקן שצבר חמש עבירות הופך רשמית ל״שחקן מורחק״, ואם הוא בכל זאת עובר עבירה נוספת — היא נרשמת על שם המאמן.', true, 'חוקי פיב״א 2024, סעיף 40.1'),
  ('rules', 'easy', 'כמה שניות יש לקבוצה לסיים התקפה לפי חוקי פיב״א?', array['14', '24', '30', '35'], 1, 'פיב״א שיחקה עם שעון של 30 שניות מאז 1956, ורק בשנת 2000 קיצרה אותו ל-24.', true, 'חוקי פיב״א 2024, סעיף 29.1.1'),
  ('rules', 'easy', 'מה גובה הטבעת מהרצפה?', array['2.90 מטר', '3.05 מטר', '3.20 מטר', '3.35 מטר'], 1, '3.05 מטר הם בדיוק עשרה רגל — הגובה של מעקה היציע שאליו תלה ג׳יימס נייסמית׳ את סלי האפרסקים ב-1891.', true, 'מפרט הציוד של פיב״א ושל האן־בי־איי'),
  ('rules', 'easy', 'כמה שחקנים מכל קבוצה נמצאים על המגרש בו-זמנית?', array['ארבעה', 'חמישה', 'שישה', 'שבעה'], 1, 'רק חמישה על הפרקט, אבל לגיליון המשחק אפשר לרשום סגל שלם — ומי שיושב על הספסל נחשב מחליף עד שהשופט מזמין אותו פנימה.', true, 'חוקי פיב״א 2024, סעיף 4.2.2'),
  ('rules', 'easy', 'כמה שניות יש לקבוצה להעביר את הכדור מהחצי האחורי לחצי הקדמי לפי פיב״א?', array['5', '8', '10', '12'], 1, 'בליגת הקולג׳ האמריקאית עדיין נותנים עשר שניות למעבר החצי — שתיים יותר מפיב״א ומהאן־בי־איי.', true, 'חוקי פיב״א 2024, סעיף 28.1.1'),
  ('rules', 'easy', 'כמה שניות מותר לשחקן תוקף לשהות ברצף ברחבת היריבה?', array['שתיים', 'שלוש', 'חמש', 'שמונה'], 1, 'הספירה רצה רק כשהקבוצה שולטת בכדור בחצי הקדמי והשעון פועל — ברגע שנזרקת זריקה לסל היא נעצרת.', true, 'חוקי פיב״א 2024, סעיף 26.1.1'),
  ('rules', 'easy', 'מהן מידות מגרש הכדורסל לפי חוקי פיב״א?', array['26 על 14 מטר', '28 על 15 מטר', '29 על 15 מטר', '30 על 16 מטר'], 1, 'מגרש אן־בי־איי מעט גדול יותר: 94 על 50 רגל, שהם כ-28.65 על 15.24 מטר.', true, 'חוקי פיב״א 2024, סעיף 2.1'),
  ('rules', 'easy', 'כמה זמן נמשכת הארכה במשחק פיב״א?', array['שלוש דקות', 'חמש דקות', 'שבע דקות', 'עשר דקות'], 1, 'מספר ההארכות אינו מוגבל — משחקים ממשיכים חמש דקות בכל פעם עד שהשוויון נשבר.', true, 'חוקי פיב״א 2024, סעיף 8.7'),
  ('rules', 'easy', 'מה המרחק של קו שלוש הנקודות בראש הקשת לפי חוקי פיב״א?', array['6.25 מטר', '6.60 מטר', '6.75 מטר', '7.24 מטר'], 2, 'בפינות המרחק מתקצר ל-6.60 מטר, כי רוחב המגרש פשוט לא מאפשר קשת שלמה עד הקו הצדדי.', true, 'חוקי פיב״א 2024, סעיף 2.5.4'),
  ('rules', 'easy', 'כמה זמן נמשכת הפסקת המחצית במשחק פיב״א?', array['10 דקות', '12 דקות', '15 דקות', '20 דקות'], 2, 'בין רבע לרבע ההפסקה קצרה בהרבה — שתי דקות בלבד, וכך גם לפני כל הארכה.', true, 'חוקי פיב״א 2024, סעיפים 8.3–8.4'),
  ('rules', 'easy', 'כמה זמן נמשך פסק זמן במשחק פיב״א?', array['30 שניות', 'דקה אחת', 'דקה וחצי', 'שתי דקות'], 1, 'החוק דורש שפסקי הזמן ייספרו במכשיר נפרד לחלוטין משעון המשחק, כדי שאי אפשר יהיה להתבלבל ביניהם.', true, 'חוקי פיב״א 2024, סעיפים 18.2.1 ו-3'),
  ('rules', 'easy', 'באיזו מידת כדור משחקים גברים בוגרים בתחרויות פיב״א?', array['מידה 5', 'מידה 6', 'מידה 7', 'מידה 8'], 2, 'נשים בוגרות משחקות במידה 6, וקטגוריות הילדים הצעירות במידה 5 — ההבדל הוא בהיקף ובמשקל הכדור.', true, 'מפרט הכדורים של פיב״א'),
  ('rules', 'easy', 'שחקן נזרק לשלוש נקודות, נעברה עליו עבירה והוא החטיא. כמה זריקות עונשין הוא מקבל?', array['אחת', 'שתיים', 'שלוש', 'שלוש ובנוסף החזקה'], 2, 'אם הכדור בכל זאת היה נכנס, הסל היה נחשב והשחקן היה מקבל זריקה חופשית אחת בלבד.', true, 'חוקי פיב״א 2024, סעיף 34.2.2'),
  ('rules', 'easy', 'כמה שחקנים לכל היותר אפשר לרשום לגיליון המשחק בקבוצת פיב״א?', array['10', '12', '14', '15'], 1, 'לצד השחקנים רשאים לשבת על הספסל מאמן ראשי ועד שמונה אנשי צוות נוספים.', true, 'חוקי פיב״א 2024, סעיף 4.2.1'),
  ('rules', 'medium', 'כמה פסקי זמן מקבלת קבוצה בחצי הראשון לפי חוקי פיב״א?', array['אחד', 'שניים', 'שלושה', 'ארבעה'], 1, 'בחצי השני מקבלים שלושה, אך לא יותר משניים מהם כששעון המשחק מראה 2:00 דקות או פחות ברבע הרביעי.', true, 'חוקי פיב״א 2024, סעיף 18.2.5'),
  ('rules', 'medium', 'מאיזו עבירה קבוצתית ברבע מתחילה הקבוצה היריבה לזרוק שתי זריקות עונשין בפיב״א?', array['מהרביעית', 'מהחמישית', 'מהשישית', 'מהשביעית'], 1, 'עבירות שנעברו בהפסקה בין רבעים נזקפות לחשבון הרבע שעומד להתחיל, ולא לזה שהסתיים.', true, 'חוקי פיב״א 2024, סעיפים 41.1.1 ו-41.1.2'),
  ('rules', 'medium', 'לאיזה רבע נספרות העבירות הקבוצתיות שנעשות בהארכה בפיב״א?', array['מתאפסות בתחילת כל הארכה', 'נספרות כהמשך ישיר לרבע הרביעי', 'נספרות בנפרד לכל הארכה', 'נספרות לחצי השני כולו'], 1, 'לכן קבוצה שנכנסה לבונוס ברבע הרביעי נשארת בבונוס גם בהארכה — בלי התחלה נקייה.', true, 'חוקי פיב״א 2024, סעיף 41.1.3'),
  ('rules', 'medium', 'מה העונש על עבירה טכנית לפי חוקי פיב״א?', array['זריקת עונשין אחת, והכדור חוזר לקבוצה שהחזיקה בו', 'שתי זריקות עונשין ובנוסף החזקה', 'זריקת עונשין אחת בלבד, בלי החזקה', 'שתי זריקות עונשין בלבד'], 0, 'אם העבירה הטכנית נעברה דווקא על ידי הקבוצה שהחזיקה בכדור, שעון הזריקות אינו מתאפס אלא ממשיך מהמקום שבו נעצר.', true, 'חוקי פיב״א 2024, סעיפים 36.3.2 ו-29.2.4'),
  ('rules', 'medium', 'מי זורק את זריקת העונשין שנפסקה בעקבות עבירה טכנית בפיב״א?', array['הקפטן של הקבוצה', 'השחקן שכלפיו הופנתה ההתנהגות', 'כל שחקן מהקבוצה היריבה, לפי בחירת המאמן', 'השחקן עם אחוזי העונשין הגבוהים בקבוצה'], 2, 'בעבירה טכנית אין שחקן שנפגע ממגע פיזי, ולכן החוק משאיר את הבחירה בידיו של המאמן הראשי.', true, 'חוקי פיב״א 2024, סעיף 43.2.2'),
  ('rules', 'medium', 'נעברה עבירה אנטי-ספורטיבית על שחקן שאינו בפעולת קליעה. מה העונש בפיב״א?', array['זריקת עונשין אחת ובנוסף החזקה', 'שתי זריקות עונשין והחזקה מקו ההכנסה בחצי הקדמי', 'שתי זריקות עונשין בלבד', 'שלוש זריקות עונשין'], 1, 'בהכנסה שאחרי העונשין שעון הזריקות מתאפס ל-14 שניות בלבד, ולא ל-24.', true, 'חוקי פיב״א 2024, סעיפים 37.2.2 ו-29.2.6'),
  ('rules', 'medium', 'כמה עבירות טכניות או אנטי-ספורטיביות מרחיקות שחקן ממשחק פיב״א?', array['שתיים, בכל שילוב ביניהן', 'שתיים, אך רק מאותו הסוג', 'שלוש, בכל שילוב', 'שלוש מאותו הסוג'], 0, 'טכנית אחת יחד עם אנטי-ספורטיבית אחת מספיקות בהחלט — אין צורך בשתיים מאותו הסוג.', true, 'חוקי פיב״א 2024, סעיף 36.2.3'),
  ('rules', 'medium', 'לכמה שניות מתאפס שעון הזריקות בפיב״א כשהקבוצה התוקפת לוקחת ריבאונד התקפי?', array['8', '14', '20', '24'], 1, 'אם דווקא ההגנה חוטפת את הריבאונד, השעון מתאפס ל-24 שניות מלאות.', true, 'חוקי פיב״א 2024, סעיף 29.2.7'),
  ('rules', 'medium', 'כמה שניות יש לזורק העונשין לשחרר את הכדור לפי חוקי פיב״א?', array['5', '8', '10', '12'], 0, 'באן־בי־איי נותנים לזורק עשר שניות — פי שניים מהזמן שיש לו במשחק בינלאומי.', true, 'חוקי פיב״א 2024, סעיף 43.2.3'),
  ('rules', 'medium', 'כמה שניות יש להכניס את הכדור מהאאוט בפיב״א?', array['3', '5', '8', '10'], 1, 'הזורק גם אינו רשאי לדרוך על המגרש כשהכדור בידו, וגם לא להכניס אותו ישירות לסל.', true, 'חוקי פיב״א 2024, סעיף 17.3.1'),
  ('rules', 'medium', 'לפי פיב״א, מאיזה מרחק נחשב מגן כמשמר צמוד, כך שמתחילה ספירת חמש שניות?', array['חצי מטר', 'מטר אחד', 'מטר וחצי', 'שני מטרים'], 1, 'לא מספיק לעמוד קרוב — המגן חייב להיות גם בעמדת הגנה חוקית ופעילה כדי שהספירה תתחיל.', true, 'חוקי פיב״א 2024, סעיף 27.1'),
  ('rules', 'medium', 'נעברה עבירה על שחקן תוך כדי פעולת קליעה, והכדור נכנס לסל. מה ההחלטה?', array['הסל נחשב, ללא זריקות עונשין', 'הסל נחשב ובנוסף זריקת עונשין אחת', 'הסל מבוטל ונפסקות שתי זריקות עונשין', 'הסל נחשב ובנוסף שתי זריקות עונשין'], 1, 'אם השחקן ספג עבירה תוך כדי קליעה ואז בחר למסור את הכדור, הוא כבר אינו נחשב כמי שהיה בפעולת קליעה.', true, 'חוקי פיב״א 2024, סעיפים 34.2.2 ו-15.1.6'),
  ('rules', 'medium', 'מה המרחק של קו שלוש הנקודות בראש הקשת באן־בי־איי?', array['6.75 מטר', '7.04 מטר', '7.24 מטר', '7.50 מטר'], 2, 'בפינות המרחק באן־בי־איי מתקצר ל-6.71 מטר, ועדיין רחוק יותר מקו הפינה של פיב״א שעומד על 6.60 מטר.', true, 'חוקי האן־בי״איי – מידות המגרש'),
  ('rules', 'medium', 'שני יריבים עוברים עבירה זה על זה כמעט בו-זמנית (עבירה כפולה). כמה זריקות עונשין נפסקות בפיב״א?', array['אף אחת', 'אחת לכל צד', 'שתיים לכל צד', 'תלוי מי החזיק בכדור'], 0, 'כל אחד מהשניים נרשם עם עבירה אישית, והמשחק פשוט מתחדש אצל הקבוצה שהחזיקה בכדור.', true, 'חוקי פיב״א 2024, סעיף 35.2'),
  ('rules', 'medium', 'שחקן קופץ מהחצי הקדמי, תופס באוויר כדור חופשי ונוחת בחצי האחורי של קבוצתו. מה ההחלטה בפיב״א?', array['חריגה לחצי האחורי', 'המשחק ממשיך, אין עבירה', 'החזקה לסירוגין', 'עבירת צעדים'], 1, 'החוק מגן על שחקן שמציל כדור באוויר, כי השליטה החדשה נוצרה כשרגליו כבר לא נגעו ברצפה.', true, 'חוקי פיב״א 2024, סעיף 30.1.2'),
  ('rules', 'hard', 'באיזו שנה קיצרה פיב״א את שעון הזריקות מ-30 שניות ל-24?', array['1994', '2000', '2004', '2010'], 1, 'האן־בי־איי הקדימה בעשרות שנים: שעון של 24 שניות פועל שם כבר מעונת 1954/55.', true, 'היסטוריית שעון הזריקות'),
  ('rules', 'hard', 'באיזו שנה הנהיגה פיב״א את איפוס שעון הזריקות ל-14 שניות אחרי ריבאונד התקפי?', array['2010', '2014', '2017', '2018'], 1, 'האן־בי־איי אימצה את אותו שינוי רק ב-2018, ארבע שנים אחרי פיב״א.', true, 'היסטוריית שעון הזריקות'),
  ('rules', 'hard', 'איזה חוק קיים באן־בי־איי אך אינו קיים כלל בחוקי פיב״א?', array['שלוש שניות הגנתי', 'שמונה שניות למעבר החצי', 'איפוס השעון ל-14 שניות', 'עבירה אנטי-ספורטיבית'], 0, 'האן־בי־איי הנהיגה אותו בעונת 2001/02, יחד עם ההיתר לשחק הגנת אזור — בפיב״א חוק שלוש השניות חל על התוקפים בלבד.', true, 'חוקי פיב״א 2024 סעיף 26 (תוקפים בלבד); חוקי האן־בי״איי'),
  ('rules', 'hard', 'מה העונש על עבירת שלוש שניות הגנתי באן־בי־איי?', array['החזקה לקבוצה התוקפת', 'עבירה טכנית: זריקת עונשין אחת, והכדור נשאר אצל ההתקפה', 'שתי זריקות עונשין', 'עבירה אישית שנרשמת על המגן'], 1, 'מכיוון שזו עבירה טכנית ולא אישית, כל שחקן מהקבוצה התוקפת יכול לזרוק את העונשין.', true, 'חוקי האן־בי״איי – עבירת שלוש שניות הגנתי'),
  ('rules', 'hard', 'כיצד מורכב צוות השופטים על הפרקט במשחק פיב״א?', array['שני שופטים שווי מעמד', 'שופט ראשי ולצידו שופט אחד או שניים', 'שלושה שופטים שווי מעמד תמיד', 'שופט ראשי ושלושה עוזרים'], 1, 'רק לשופט הראשי יש סמכות להכריע כשהשופטים חלוקים, והוא גם זה שבוחר את כדור המשחק לפני הפתיחה.', true, 'חוקי פיב״א 2024, סעיפים 45.1 ו-46.11'),
  ('rules', 'hard', 'מי הם ארבעת שופטי השולחן במשחק פיב״א?', array['רשם, עוזר רשם, שען ומפעיל שעון הזריקות', 'רשם, שען, מפעיל שעון הזריקות ומשקיף', 'שני רשמים ושני שענים', 'רשם, שען, רופא ומשקיף'], 0, 'הקומיסר, כשהוא נוכח, יושב בדיוק בין הרשם לשען ותפקידו לפקח על עבודתם.', true, 'חוקי פיב״א 2024, סעיפים 45.2 ו-45.3'),
  ('rules', 'hard', 'מהיכן מתחדש המשחק בפתיחת הרבע השני, השלישי והרביעי בפיב״א?', array['מקפיצה במעגל האמצע', 'מהכנסה בקו האמצע, מול שולחן הרשמים', 'מהכנסה מהקצה של הקבוצה המתגוננת', 'מהכנסה מקו העונשין המוארך'], 1, 'קפיצה במעגל האמצע מתרחשת פעם אחת בלבד בכל המשחק — בפתיחת הרבע הראשון, וכל השאר נקבע לפי חץ ההחזקה לסירוגין.', true, 'חוקי פיב״א 2024, סעיפים 17.2.3 ו-12.6'),
  ('rules', 'hard', 'שחקן קלע בטעות לסל של קבוצתו שלו. כיצד נרשמות הנקודות בפיב״א?', array['הסל אינו נחשב כלל', 'שתי נקודות ליריבה, על שם הקולע', 'שתי נקודות ליריבה, על שם הקפטן שנמצא על המגרש', 'שלוש נקודות ליריבה'], 2, 'החוק נמנע מלרשום סל על שם שחקן יריב שכלל לא נגע בכדור, ולכן הנקודות נזקפות לקפטן.', true, 'חוקי פיב״א 2024, סעיף 16.2.2'),
  ('rules', 'hard', 'שחקן קולע במכוון לסל של קבוצתו שלו. מה ההחלטה בפיב״א?', array['שתי נקודות ליריבה', 'הסל אינו נחשב — זו עבירת חוק', 'עבירה טכנית', 'הסל נחשב ובנוסף נרשמת עבירה טכנית'], 1, 'אותו היגיון חל על העברת הכדור דרך הסל מלמטה כלפי מעלה — גם היא נחשבת עבירת חוק.', true, 'חוקי פיב״א 2024, סעיפים 16.2.3 ו-16.2.4'),
  ('rules', 'hard', 'כמה זמן חייב להופיע על השעון בפיב״א כדי ששחקן יוכל לתפוס כדור מהכנסה ולזרוק לסל?', array['0.1 שניות', '0.2 שניות', '0.3 שניות', '0.5 שניות'], 2, 'עם 0.2 או 0.1 שניות בלבד, הסל היחיד שיכול להיחשב הוא נגיעה מכוונת (טיפ) או הטבעה ישירה.', true, 'חוקי פיב״א 2024, סעיף 16.2.5'),
  ('rules', 'hard', 'מגן ביצע הגנת סל (goaltending) בזריקת העונשין האחרונה. מה ההחלטה בפיב״א?', array['נקודה אחת לקבוצה התוקפת בלבד', 'נקודה אחת, ובנוסף עבירה טכנית על המגן', 'הזריקה נזרקת מחדש', 'שתי נקודות לקבוצה התוקפת'], 1, 'כשהגנת הסל נעשית על זריקה מהמגרש נרשמות הנקודות כאילו הכדור נכנס — שתיים או שלוש, לפי מקום הזריקה.', true, 'חוקי פיב״א 2024, סעיפים 31.3.2 ו-31.3.3'),
  ('rules', 'hard', 'כמה אתגרים (צ׳לנג׳) מקבל מאמן ראשי במשחק פיב״א שבו פועלת מערכת השידור החוזר?', array['אחד בלבד, בכל מקרה', 'אחד, ועוד אחד אם צדק', 'שניים', 'ללא הגבלה'], 0, 'האתגר נשרף גם כשהבדיקה מוכיחה שהמאמן צדק וההחלטה מתהפכת — ולכן יש לו בדיוק הזדמנות אחת במשחק.', true, 'חוקי פיב״א 2024, נספח F.4'),
  ('rules', 'hard', 'מה רוחב הרחבה (אזור שלוש השניות) לפי חוקי פיב״א?', array['3.60 מטר', '4.90 מטר', '5.80 מטר', '6.00 מטר'], 1, 'קו העונשין עצמו באורך 3.60 מטר בלבד — כלומר הוא צר יותר מהרחבה שהוא סוגר.', true, 'חוקי פיב״א 2024, סעיף 2.5.3'),
  ('rules', 'hard', 'שחקן מחזיק בכדור, נופל על הרצפה ומחליק עליה. מה ההחלטה בפיב״א?', array['עבירת צעדים בכל מקרה', 'חוקי — אך אם יתגלגל או ינסה לקום עם הכדור, תיפסק עבירת צעדים', 'החזקה לסירוגין', 'חוקי בכל מקרה, גם אם יקום עם הכדור'], 1, 'גם שחקן ששוכב או יושב על הרצפה ומשיג שם שליטה בכדור פועל באופן חוקי לחלוטין — הבעיה מתחילה רק בגלגול או בקימה.', true, 'חוקי פיב״א 2024, סעיף 25.2.2'),
  ('records', 'easy', 'כמה נקודות כבש וילט צ''מברלין במשחק NBA אחד, בשיא שלא נשבר עד היום?', array['100', '81', '83', '73'], 0, 'המשחק נערך באולם קטן בהרשי שבפנסילבניה ב-1962, ומעולם לא נמצא ממנו אפילו קטע וידאו אחד.', true, 'ויקיפדיה – משחק 100 הנקודות של צ''מברלין'),
  ('records', 'easy', 'מי כבש 83 נקודות במשחק במרץ 2026 ונכנס למקום השני בכל הזמנים?', array['באם אדבאיו', 'לוקה דונצ''יץ''', 'ג''ואל אמבייד', 'דונובן מיטשל'], 0, 'מיאמי ניצחה 129:150 את וושינגטון, ואדבאיו עלה לקו העונשין 43 פעמים — יותר מכל שחקן במשחק NBA אי פעם.', true, 'NBA.com, ESPN'),
  ('records', 'hard', 'כמה זריקות עונשין קלע באם אדבאיו בערב 83 הנקודות, בשיא NBA חדש?', array['28', '32', '36', '40'], 2, 'השיא הקודם, 28 עונשין, נקבע בידי צ''מברלין בערב 100 הנקודות והושווה מאז רק פעם אחת.', true, 'ויקיפדיה – משחק 83 הנקודות של אדבאיו'),
  ('records', 'easy', 'מול איזו קבוצה כבש קובי בראיינט 81 נקודות ב-2006?', array['טורונטו רפטורס', 'דאלאס מאבריקס', 'יוטה ג''אז', 'ניו יורק ניקס'], 0, 'בראיינט קלע 55 נקודות במחצית השנייה לבדו — יותר מכל קבוצת טורונטו, שכבשה בה 41.', true, 'ויקיפדיה – משחק 81 הנקודות של קובי'),
  ('records', 'medium', 'מהו שיא הריבאונדים של שחקן במשחק NBA אחד?', array['55', '45', '40', '50'], 0, 'צ''מברלין שיחק את כל 48 הדקות מול בוסטון, הוסיף 34 נקודות — ופילדלפיה בכל זאת הפסידה בשלוש נקודות.', true, 'NBA.com, History.com'),
  ('records', 'hard', 'מי מחזיק בשיא של 30 אסיסטים במשחק NBA אחד?', array['סקוט סקיילס', 'ג''ון סטוקטון', 'מג''יק ג''ונסון', 'ראסל וסטברוק'], 0, 'אורלנדו ניצחה באותו ערב בהפרש 39, והוא עצמו הוסיף 22 נקודות; השיא הקודם עמד על 29.', true, 'NBA.com – 30 assists record'),
  ('records', 'medium', 'מי מחזיק בשיא הנקודות של שחקן ברבע אחד ב-NBA — 37 נקודות?', array['קליי תומפסון', 'סטפן קרי', 'קווין דוראנט', 'ג''יימס הארדן'], 0, 'הוא קלע באותו רבע 13 מתוך 13 מהשדה, מהן 9 מתוך 9 משלוש — רבע מושלם לחלוטין.', true, 'NBA.com / Warriors'),
  ('records', 'medium', 'כמה שלשות קלע קליי תומפסון במשחק שהוא שיא NBA?', array['14', '12', '13', '16'], 0, 'הוא סיים את המשחק ההוא עם 52 נקודות, וגולדן סטייט גברה על שיקגו בהפרש 25.', true, 'ESPN, Sky Sports'),
  ('records', 'easy', 'מהו שיא השלשות של שחקן בעונה אחת ב-NBA?', array['402', '286', '350', '378'], 0, 'השני ברשימה, ג''יימס הארדן, נעצר על 378 — וחמישה מששת המקומות הראשונים בטבלה שייכים לסטפן קרי.', true, 'NBA.com, StatMuse'),
  ('records', 'medium', 'סטפן קרי היה השחקן הראשון בהיסטוריה שעבר איזה רף שלשות בקריירה?', array['4,000', '3,000', '2,500', '5,000'], 0, 'השיא הקודם היה של ריי אלן — 2,973 שלשות — וקרי הוסיף עליו יותר מאלף.', true, 'NBA.com, ESPN'),
  ('records', 'hard', 'מהו ממוצע הנקודות הגבוה ביותר שרשם שחקן בעונה שלמה ב-NBA?', array['50.4', '44.8', '37.1', '40.2'], 0, 'באותה עונה צ''מברלין כבש 4,029 נקודות ושיחק בממוצע 48.5 דקות למשחק — יותר מאורכו של משחק רגיל.', true, 'NBA.com – 1961-62 season recap'),
  ('records', 'medium', 'מהו רצף הניצחונות הארוך ביותר בהיסטוריית ה-NBA?', array['33', '27', '24', '20'], 0, 'הרצף של הלייקרס נעצר מול מילווקי בינואר 1972, והם סיימו את העונה עם 69 ניצחונות ו-13 הפסדים וזכו באליפות.', true, 'NBA.com / Lakers'),
  ('records', 'hard', 'המשחק עתיר הנקודות בהיסטוריית ה-NBA הסתיים 184:186 בשלוש הארכות. מי ניצחה?', array['דטרויט פיסטונס', 'דנוור נאגטס', 'פיניקס סאנס', 'סן אנטוניו ספרס'], 0, '370 נקודות בסך הכול, וזה המשחק היחיד בהיסטוריה שבו ארבעה שחקנים כבשו 40 נקודות ומעלה.', true, 'NBA.com, Basketball-Reference'),
  ('records', 'hard', 'המשחק דל הנקודות בהיסטוריית ה-NBA הסתיים 18:19 ב-1950. איזה שינוי נולד בעקבותיו?', array['שעון ה-24 שניות', 'קו השלוש נקודות', 'הגדלת המגרש', 'ביטול ההארכות'], 0, 'פורט וויין פשוט החזיקה בכדור בלי לזרוק — ובלי שעון זריקות אף אחד לא יכול היה לאלץ אותה לשחק.', true, 'Stew Thornley, KVRR'),
  ('records', 'medium', 'מי מחזיק בשיא הנקודות של שחקן במשחק פלייאוף — 63 נקודות?', array['מייקל ג''ורדן', 'לברון ג''יימס', 'קובי בראיינט', 'אלג''ין ביילור'], 0, 'הוא הפסיד את המשחק ההוא לסלטיקס בשתי הארכות, ולארי בירד תיאר אותו כ«אלוהים מחופש למייקל ג''ורדן».', true, 'NBA.com, History.com'),
  ('records', 'hard', 'מי מחזיק בשיא של 17 חסימות במשחק NBA אחד?', array['אלמור סמית''', 'מארק איטון', 'דיקמבה מוטומבו', 'חאקים אולאג''ואן'], 0, 'אחת עשרה מהחסימות נרשמו כבר במחצית הראשונה, וגם זה שיא שעומד עד היום.', true, 'NBA.com – most blocks in a game'),
  ('records', 'easy', 'מי מחזיק בשיא הטריפל-דאבלים בקריירה ב-NBA?', array['ראסל וסטברוק', 'ניקולה יוקיץ''', 'אוסקר רוברטסון', 'מג''יק ג''ונסון'], 0, 'הוא הראשון שהגיע ל-200 טריפל-דאבלים, אחרי שב-2021 עקף את 181 של אוסקר רוברטסון.', true, 'NBA.com, CBS Sports'),
  ('records', 'hard', 'כמה טריפל-דאבלים רשם ראסל וסטברוק בעונה אחת, בשיא NBA?', array['42', '37', '31', '25'], 0, 'באותה עונה הוא גם סיים בממוצע טריפל-דאבל — הראשון שעשה זאת מאז 1962.', true, 'NBA.com, Olympics.com'),
  ('records', 'medium', 'מי היה השחקן הראשון שסיים עונה שלמה ב-NBA בממוצע של טריפל-דאבל?', array['אוסקר רוברטסון', 'מג''יק ג''ונסון', 'ראסל וסטברוק', 'ג''ייסון קיד'], 0, 'זה קרה בעונת 1961/62 — בדיוק העונה שבה צ''מברלין כבש 100 נקודות במשחק אחד.', true, 'NBA.com – 1961-62 season'),
  ('records', 'hard', 'הטריפל-דאבל המהיר בהיסטוריית ה-NBA הושלם תוך 14 דקות ו-33 שניות. מי רשם אותו?', array['ניקולה יוקיץ''', 'ראסל וסטברוק', 'מג''יק ג''ונסון', 'לוקה דונצ''יץ'''], 0, 'השיא הקודם, 17 דקות, שרד מ-1955, והוא סיים את הערב עם 30 נקודות, 17 אסיסטים ו-15 ריבאונדים.', true, 'Guinness World Records, SI'),
  ('records', 'medium', 'מי השחקן היחיד בהיסטוריית ה-NBA שרשם במשחק אחד 30 נקודות, 20 ריבאונדים ו-20 אסיסטים?', array['ניקולה יוקיץ''', 'וילט צ''מברלין', 'ראסל וסטברוק', 'אוסקר רוברטסון'], 0, 'הקו המדויק היה 31 נקודות, 21 ריבאונדים ו-22 אסיסטים, במשחק הארכה מול פיניקס במרץ 2025.', true, 'ויקיפדיה – עונת 2024/25 של דנוור'),
  ('records', 'medium', 'מי מחזיק בשיא האסיסטים בקריירה ב-NBA — 15,806?', array['ג''ון סטוקטון', 'כריס פול', 'מג''יק ג''ונסון', 'ג''ייסון קיד'], 0, 'הוא מחזיק גם בשיא החטיפות בקריירה, 3,265, ובשני השיאים האלה אף אחד לא באמת קרוב אליו.', true, 'Basketball-Reference, NBA.com'),
  ('records', 'easy', 'מי החזיק בשיא הנקודות בקריירה ב-NBA עד שלברון ג''יימס עקף אותו?', array['קרים עבד אל-ג''בר', 'קרל מאלון', 'מייקל ג''ורדן', 'קובי בראיינט'], 0, 'השיא שלו, 38,387 נקודות, שרד כמעט 39 שנה ונבנה ברובו מזריקה אחת: הסקייהוק.', true, 'NBA.com, Basketball-Reference'),
  ('records', 'easy', 'בכמה אליפויות NBA זכה ביל ראסל בקריירה?', array['11', '8', '9', '6'], 0, 'מתוכן שמונה ברצף, בין 1959 ל-1966 — רצף שאף קבוצה לא התקרבה אליו מאז.', true, 'NBA.com, Basketball-Reference'),
  ('records', 'easy', 'מהו שיא הניצחונות של קבוצה בעונה סדירה אחת ב-NBA?', array['73', '72', '70', '69'], 0, 'גולדן סטייט עקפה בעונה ההיא את 72 הניצחונות של שיקגו — אבל הפסידה בגמר.', true, 'NBA.com, Basketball-Reference'),
  ('records', 'medium', 'מי שיחק 1,192 משחקים ברצף ב-NBA בלי להחמיץ אף אחד — שיא כל הזמנים?', array['א.סי. גרין', 'קרל מאלון', 'ג''ון סטוקטון', 'רוברט פאריש'], 0, 'מדובר ביותר מ-14 עונות שלמות בלי להחמיץ ערב משחק אחד.', true, 'NBA.com, Basketball-Reference'),
  ('records', 'hard', 'מהו רצף הניצחונות הארוך ביותר בכדורסל הקולג''ים בארה"ב, שנרשם על ידי UCLA?', array['88', '60', '47', '100'], 0, 'הרצף נבנה תחת המאמן ג''ון ווודן ונקטע ב-1974 דווקא מול נוטרדאם.', true, 'NCAA records'),
  ('records', 'easy', 'בכמה תארי יורוליג (גביע אירופה לאלופות) זכתה מכבי תל אביב?', array['6', '4', '3', '8'], 0, '1977, 1981, 2001, 2004, 2005 ו-2014 — והתואר הראשון הגיע באותה עונה שבה נאמר «אנחנו על המפה».', true, 'EuroLeague, maccabi.co.il'),
  ('records', 'medium', 'בכמה נקודות ניצחה מכבי תל אביב את ורזה בגמר גביע אירופה 1977?', array['נקודה אחת', 'שלוש נקודות', 'חמש נקודות', 'שבע נקודות'], 0, 'המשחק נערך בבלגרד והסתיים 77:78 — התואר האירופי הראשון של קבוצה ישראלית בכדורסל.', true, 'ויקיפדיה, ONE, maccabi.co.il'),
  ('records', 'hard', 'בכמה נקודות ניצחה מכבי תל אביב את סקיפר בולוניה בגמר היורוליג 2004?', array['44', '20', '30', '55'], 0, 'התוצאה 74:118 היא ההפרש הגדול ביותר אי פעם בגמר אירופי, ואנתוני פארקר נבחר ל-MVP.', true, 'EuroLeague, maccabi.co.il'),
  ('records', 'hard', 'מי כבש 50 נקודות במשחק יורוליג — שיא כל הזמנים של המפעל?', array['ניג''ל הייז-דייוויס', 'שיין לרקין', 'סשה וזנקוב', 'מייק ג''יימס'], 0, 'הוא הראשון שעבר את רף 50 הנקודות ביורוליג; במקום השני נמצא שיין לרקין עם 49.', true, 'EuroLeague, BasketNews'),
  ('records', 'medium', 'לאיזו קבוצה יש הכי הרבה תארי יורוליג בהיסטוריה?', array['ריאל מדריד', 'צסק״א מוסקבה', 'פנאתינייקוס', 'מכבי תל אביב'], 0, 'אחד עשר תארים לריאל מדריד, ואחריה צסק״א מוסקבה עם שמונה.', true, 'EuroLeague, ויקיפדיה'),
  ('records', 'hard', 'מי המאמן עם מספר תארי היורוליג הגדול ביותר — תשעה?', array['ז''ליקו אוברדוביץ''', 'פיני גרשון', 'דייויד בלאט', 'דושקו איבנוביץ'''], 0, 'תשעה תארים עם חמישה מועדונים שונים — יותר מכל מועדון בהיסטוריה חוץ מריאל מדריד.', true, 'EuroLeague, BasketNews'),
  ('records', 'medium', 'מי מלך הקלעים של ליגת העל הישראלית בכדורסל בכל הזמנים?', array['דורון ג''מצ''י', 'מיקי ברקוביץ''', 'עופר עשד', 'בועז ינאי'], 0, '9,592 נקודות — בערך 1,360 יותר ממיקי ברקוביץ'' שנמצא במקום השני.', true, 'מנהלת ליגת העל – basket.co.il'),
  ('records', 'hard', 'מכבי תל אביב זכתה ב-23 אליפויות ישראל ברצף. איזו קבוצה שברה את הרצף ב-1993?', array['הפועל גליל עליון', 'הפועל תל אביב', 'מכבי חיפה', 'הפועל ירושלים'], 0, 'הקבוצה של פיני גרשון הדיחה את מכבי בחצי הגמר וגברה בגמר על הפועל תל אביב.', true, 'ויקיפדיה – עונת 1992/93, ynet'),
  ('records', 'easy', 'מי היה השחקן הישראלי הראשון ששיחק במשחק NBA?', array['עומרי כספי', 'דני אבדיה', 'דורון שפר', 'ים מדר'], 0, 'הוא נבחר במקום ה-23 בדראפט 2009 בידי סקרמנטו — הישראלי הראשון שנבחר בסיבוב הראשון.', true, 'ויקיפדיה, Haaretz'),
  ('records', 'medium', 'באיזה מקום בדראפט ה-NBA נבחר דני אבדיה?', array['תשיעי', 'רביעי', 'חמישה־עשר', 'עשרים ושלושה'], 0, 'ב-2026 הוא הפך גם לישראלי הראשון בהיסטוריה שנבחר למשחק האולסטאר של ה-NBA.', true, 'ויקיפדיה – Deni Avdija'),
  ('records', 'medium', 'מהו שיא הנקודות של דני אבדיה במשחק NBA אחד?', array['43', '35', '51', '28'], 0, 'באותו ערב הוא הוסיף גם 15 ריבאונדים — צירוף שאף שחקן של וושינגטון לא רשם מאז 1987.', false, 'ויקיפדיה, Land of Basketball'),
  ('records', 'hard', 'מהו ההישג הטוב ביותר של נבחרת ישראל הבוגרת בכדורסל באליפות אירופה?', array['מדליית כסף ב-1979', 'מדליית ארד ב-1977', 'מדליית כסף ב-1953', 'מקום רביעי ב-2015'], 0, 'זו המדליה היחידה של נבחרת ישראל הבוגרת באליפות אירופה עד עצם היום הזה.', true, 'ויקיפדיה – נבחרת ישראל בכדורסל, וואלה ספורט'),
  ('tactics', 'easy', 'איזו עמדה במגרש מסומנת במספר 1 בשפת המאמנים?', array['רכז', 'קלע', 'כנף', 'סנטר'], 0, 'המספור 1–5 קיים כדי שמאמן יוכל לשרטט תרגיל על הלוח בלי לכתוב שמות — ולכן הוא כמעט זהה בכל העולם.', true, 'ויקיפדיה עברית — כדורסלן / עמדות שחקנים'),
