  ('tactics', 'easy', 'מהו «מסך» (screen / pick) בהתקפה?', array['שחקן עומד יציב וחוסם בגופו את דרכו של מגן', 'זריקה מעל ידו המושטת של המגן', 'מסירה גבוהה שנקלעת ישירות מהאוויר', 'מהלך שבו שני מגנים תוקפים יחד את הכדור'], 0, 'מעמיד המסך חייב להיות עומד ויציב ברגע המגע — אם הוא זז, זו כבר עבירה התקפית.', true, 'Coach''s Clipboard — Basketball Terminology'),
  ('tactics', 'easy', 'בפיק-אנד-רול, מה עושה מעמיד המסך במהלך ה«רול»?', array['מתגלגל לכיוון הסל מיד אחרי המסך', 'נשאר לעמוד במקומו עד סוף ההתקפה', 'רץ אחורה לעבר ההגנה', 'יוצא לפינה ומחכה למסירה'], 0, 'הרול מייצר מצב של 2 נגד 1 — ההגנה חייבת לבחור בין בעל הכדור למתגלגל, ומישהו תמיד נשאר פתוח.', true, 'Hooper University / Coach''s Clipboard — Ball Screen Offense'),
  ('tactics', 'medium', 'איך נקרא המהלך שבו מעמיד המסך יוצא החוצה לקשת לזריקה במקום להתגלגל לסל?', array['פיק-אנד-פופ', 'פיק-אנד-רול', 'הנד-אוף', 'בק-דור'], 0, 'בגלל הפופ הפכו סנטרים שקולעים שלשות לנשק — אי אפשר להשאיר סנטר נסוג מתחת לסל מולם.', true, 'The Basketball Action Dictionary'),
  ('tactics', 'hard', 'מהו «סליפ» (slip) בפיק-אנד-רול?', array['החוסם עוזב לכיוון הסל עוד לפני שיצר מגע במסך', 'החוסם מעמיד שני מסכים ברצף לאותו שחקן', 'החוסם מחליף עמדה עם הרכז', 'החוסם מוסר את הכדור מיד אחרי המסך'], 0, 'הסליפ הוא התשובה הקלאסית להגנה שקופצת אגרסיבית על המסך — משאירים אותה תוקפת אוויר.', true, 'Hoop Student — Slip Screen / Basketball Action Dictionary'),
  ('tactics', 'easy', 'מהי המטרה של «בלוק-אאוט» מתחת לסל?', array['למצוא את היריב ולהחזיק אותו מאחורי הגב לפני שהכדור יורד', 'לחסום את הזריקה של היריב באוויר', 'לעצור את הכדרור של בעל הכדור', 'לעכב את היריב בהוצאת הכדור מהקו'], 0, 'הריבאונד נקבע בשנייה שלפני שהכדור נוגע בטבעת — מי שמצא גוף ראשון כמעט תמיד יזכה בכדור.', true, 'Basketball For Coaches — Rebounding fundamentals'),
  ('tactics', 'easy', 'מה מאפיין הגנה אישית (man-to-man)?', array['לכל מגן יש שחקן יריב מסוים שהוא אחראי עליו', 'כל מגן שומר על שטח קבוע במגרש', 'שני מגנים שומרים על כל תוקף', 'רק שלושה שחקנים מגינים בכל רגע'], 0, 'בהגנה אישית טובה עדיין יש עזרה — «אישית» לא אומר שכל אחד נשאר לבד מול היריב שלו.', true, 'Basketball For Coaches — Shell Drill / man-to-man principles'),
  ('tactics', 'easy', 'מה מאפיין הגנת אזור (zone)?', array['כל מגן אחראי על שטח מוגדר במגרש ולא על שחקן מסוים', 'כל מגן נצמד לשחקן קבוע לאורך כל המשחק', 'ההגנה מתחילה רק אחרי חצי מגרש', 'מותר להשתמש בה רק ברבע האחרון'], 0, 'הגנת אזור טובה נעה עם הכדור — היא לא עומדת במקום, אלא מחליפה עמדות בכל מסירה.', true, 'Coach''s Clipboard — Zone Defense'),
  ('tactics', 'medium', 'בהגנת אזור 2-3, איזה אזור נחשב לחולשה הקלאסית שממנה מפרקים אותה?', array['הפוסט הגבוה, סביב קו העונשין', 'הפינה הימנית מחוץ לקשת', 'הצד החלש מאחורי הקשת', 'השטח ממש מתחת לטבעת'], 0, 'שחקן שמקבל כדור במרכז קו העונשין הוא סיוט לאזור — הוא רואה את הסל ואת שני צידי המגרש בבת אחת.', true, 'Daily Orange / Coach''s Clipboard — 2-3 zone weaknesses'),
  ('tactics', 'easy', 'מהו «טרנזישן» בשפת המשחק?', array['המעבר המהיר מהגנה להתקפה או מהתקפה להגנה', 'החלפת שחקנים מהספסל', 'פסק זמן קצר של 20 שניות', 'מעבר מהגנת אזור להגנה אישית'], 0, 'רוב הסלים הקלים במשחק נופלים בשניות הראשונות של הטרנזישן — לפני שההגנה הספיקה למצוא את השחקנים שלה.', true, 'Coach''s Clipboard — Basketball Terminology'),
  ('tactics', 'easy', 'מה המונח העברי ל«ריבאונד»?', array['כדור חוזר', 'כדור קפיצה', 'כדור מת', 'כדור חוץ'], 0, 'ריבאונד הגנתי הוא הסיום של כל הגנה — בלעדיו כל העבודה שלפניו נמחקת ברגע אחד.', true, 'ויקיפדיה עברית — כדורסל'),
  ('tactics', 'medium', 'מה המונח העברי ל«טרנאובר» (turnover)?', array['איבוד כדור', 'חטיפה', 'בישול', 'הרחקה'], 0, 'איבוד וחטיפה הם שני צדדים של אותו מטבע — אבל לא כל איבוד נגרם מחטיפה, לפעמים זו פשוט מסירה רעה.', true, 'ויקיפדיה עברית — כדורסל'),
  ('tactics', 'easy', 'כמה שניות יש לקבוצה מרגע קבלת הכדור ועד לזריקה שנוגעת בטבעת?', array['24', '30', '20', '35'], 0, 'שעון הזריקות נולד כדי שקבוצה מובילה לא תוכל פשוט להחזיק בכדור עד סוף המשחק ולהקפיא אותו.', true, 'FIBA Official Basketball Rules 2024'),
  ('tactics', 'medium', 'לפי חוקי פיב"א, כמה שניות יש לקבוצה להעביר את הכדור לחצי המגרש של היריבה?', array['8', '10', '6', '12'], 0, 'פיב"א קיצרה את הזמן מ-10 שניות ל-8 בשנת 2000 כדי להאיץ את המשחק, וה-NBA הצטרפה שנה אחריה.', true, 'FIBA Backcourt Rule (8 Seconds) / Wikipedia — Time line'),
  ('tactics', 'medium', 'אחרי ריבאונד התקפי, לכמה שניות מתאפס שעון הזריקות?', array['14', '24', '12', '10'], 0, 'החוק נועד לתגמל ריבאונד התקפי בהתקפה מהירה — ולכן מתאמנים על «זריקה שנייה» מיד, בלי לסדר תרגיל חדש.', true, 'FIBA.basketball — NBA implements FIBA''s 14-second shot clock rule'),
  ('tactics', 'medium', 'בכללי פיב"א, החל מאיזו עבירה קבוצתית ברבע מקבלת הקבוצה התוקפת זריקות עונשין?', array['החמישית', 'הרביעית', 'השישית', 'השביעית'], 0, 'לכן מאמנים סופרים עבירות כבר בתחילת רבע — קבוצה שנכנסה לבונוס אחרי שתי דקות תשחק הגנה זהירה מדי.', true, 'Wikipedia — Bonus (basketball) / FIBA rules'),
  ('tactics', 'hard', 'איך נקראת שיטת ההגנה על פיק-אנד-רול שבה הגבוה נסוג לכיוון הסל ומחזיק מלפניו גם את בעל הכדור וגם את המתגלגל?', array['דרופ (drop)', 'הדג'' (hedge)', 'סוויץ'' (switch)', 'בליץ (blitz)'], 0, 'דרופ מגן על הסל אבל מוותר על זריקת הביניים — ולכן קלע שיודע לעצור ולזרוק מקו העונשין מקבל ממנו מתנה.', true, 'Level Up Basket / Hoop Brief — Pick-and-Roll Coverages'),
  ('tactics', 'hard', 'מהי הגנת «הדג''» (hedge, נקראת גם show) על מסך?', array['מגן החוסם קופץ החוצה לעצור את בעל הכדור ואז חוזר לשחקן שלו', 'שני המגנים מחליפים ביניהם שחקנים', 'הגבוה נסוג עד לקו הרצפה', 'המגן עובר מתחת למסך ומוותר על הזריקה'], 0, 'המחיר של הדג'' הוא רגע שבו החוסם נשאר חופשי — ובדיוק בשביל הרגע הזה נולד ה«סליפ».', true, 'Level Up Basket / Basketball Action Dictionary'),
  ('tactics', 'hard', 'בהגנת «אייס» (ICE, נקראת גם blue או down), מה עושה ההגנה?', array['מסרבת לתת לבעל הכדור להשתמש במסך ודוחפת אותו לכיוון קו הצד', 'מחליפה שחקנים בין כל חמשת המגנים', 'מכפילה שני מגנים על השחקן בפינה', 'נסוגה מיד לאזור 2-3'], 0, 'אייס עובד בעיקר על מסך בצד המגרש — קו הצד משמש שם כמגן חמישי, כי אי אפשר לעקוף אותו.', true, 'Hoop Brief / Basketball Action Dictionary — PnR coverages'),
  ('tactics', 'medium', 'המאמן צועק «סוויץ''!» ברגע שהיריב מעמיד מסך. מה הוא מבקש מהמגנים?', array['שיחליפו ביניהם את השחקנים שעליהם הם שומרים', 'ששניהם יתקפו יחד את בעל הכדור', 'שיעברו להגנת אזור', 'שאחד מהם ירוץ אחורה לשמור על הסל'], 0, 'הבעיה בהחלפה היא ה«מיסמאץ''» — רכז קטן שנתקע מול סנטר, ובדיוק את זה ההתקפה מחפשת ליצור.', true, 'Level Up Basket — Switching coverage'),
  ('tactics', 'hard', 'מהו «בליץ» (blitz) או «טראפ» על פיק-אנד-רול?', array['שני מגנים תוקפים יחד את בעל הכדור ומכריחים אותו להיפטר ממנו', 'הגבוה נסוג עד מתחת לסל', 'המגן עובר מעל המסך ומסתדר לבד', 'ההגנה עוברת לאזור באמצע ההתקפה'], 0, 'בליץ מייצר איבודי כדור, אבל משאיר 4 נגד 3 בגב ההגנה — ולכן הוא שמור לרגעים ולשחקנים ספציפיים.', true, 'Hoop Brief — Blitz coverage'),
  ('tactics', 'easy', 'מהי «התקפת פרץ» (fast break)?', array['ריצה מהירה לסל לפני שההגנה היריבה הספיקה להתארגן', 'תרגיל מסודר שרצים בחצי מגרש', 'הגנה לוחצת על כל המגרש', 'סדרת מסירות עד סוף שעון הזריקות'], 0, 'המסירה הראשונה אחרי הריבאונד ההגנתי — ה«אאוטלט» — היא זו שמכריעה אם בכלל יהיה פרץ.', true, 'Coach''s Clipboard — Fast Break'),
  ('tactics', 'medium', 'מגן עוזב את השחקן שלו כדי לעזור בצבע, והכדור נמסר החוצה לשחקן הפתוח. איך נקראת הריצה שלו חזרה אל הזורק?', array['קלוז-אאוט', 'בלוק-אאוט', 'דניאל', 'הדג'''], 0, 'קלוז-אאוט טוב מסתיים בצעדים קצרים ובלימה — מי שרץ ישר ובגדול נענש בכדרור אחד לצד ובפריצה חופשית לסל.', true, 'Basketball For Coaches — Shell Drill / closeouts'),
  ('tactics', 'hard', 'מהו «צד העזרה» (help side, נקרא גם weak side)?', array['הצד של המגרש הרחוק מהכדור', 'הצד שבו נמצא הכדור באותו רגע', 'השטח שמתחת לסל בלבד', 'האזור שמאחורי קו האמצע'], 0, 'מגני צד העזרה עומדים על קו מדומה בין הכדור לסל, ולכן הם רואים גם את הכדור וגם את השחקן שלהם בלי לסובב את הראש.', true, 'Basketball For Coaches — Shell Drill, split line'),
  ('tactics', 'medium', 'מהו חיתוך «בק-דור» (backdoor)?', array['חיתוך מאחורי גב המגן אל הסל, בזמן שהמגן עסוק בדחיקת קו המסירה', 'חיתוך מהפינה החוצה אל הקשת', 'מסירה שמבוצעת מאחורי הגב', 'מסך שמועמד מאחורי גבו של המגן'], 0, 'הבק-דור הוא העונש הישיר על הגנה שדוחקת חזק מדי — ככל שהמגן נצמד יותר לקו המסירה, כך הדלת האחורית פתוחה יותר.', true, 'Wikipedia — Princeton offense / Basketball Action Dictionary'),
  ('tactics', 'hard', 'איזו התקפה מזוהה יותר מכל עם חיתוכי הבק-דור, ונקראת על שם האוניברסיטה שבה פיתח אותה פיט קריל?', array['התקפת פרינסטון', 'התקפת המשולש', 'התקפת פלקס', 'מערך הורנס'], 0, 'קריל העביר את הסנטר מהפוסט הנמוך לפוסט הגבוה — וכך פינה את כל הרחבה לחיתוכים אל הסל.', true, 'Wikipedia — Princeton offense / SI Vault'),
  ('tactics', 'hard', 'מי נחשב לאדריכל של «התקפת המשולש», שאיתה זכה פיל ג''קסון באליפויות עם שיקגו ולוס אנג''לס?', array['טקס ווינטר', 'פיט קריל', 'דין סמית''', 'ג''ון ווּדן'], 0, 'השם הרשמי של השיטה הוא «התקפת שלושת הפוסטים», והמשולש עצמו נוצר משחקן בפינה, שחקן בכנף ופוסט נמוך באותו צד.', true, 'Wikipedia — Triangle offense / SI'),
  ('tactics', 'medium', 'במערך «הורנס», איפה עומדים שני השחקנים הגבוהים?', array['בשני המרפקים, בשני קצות קו העונשין', 'בשתי הפינות של המגרש', 'משני צידי הסל, בפוסט הנמוך', 'מחוץ לקשת משני צידי הרכז'], 0, 'השם נולד מהצורה — שני גבוהים בולטים כמו קרניים של שור, ולהגנה אין צד «נכון» לדחוף אליו את בעל הכדור.', true, 'The Hoops Geek / Basketball Dictionary — Horns'),
  ('tactics', 'medium', 'מהו «מרפק» (elbow) בשפת המגרש?', array['הנקודה שבה קו העונשין נפגש עם קו הצד של הרחבה', 'הפינה של המגרש ליד קו הרצפה', 'מרכז הקשת בראש המפתח', 'השטח שמתחת לטבעת'], 0, 'מהמרפק יש גם זווית זריקה נוחה וגם מסירה קצרה לשני צידי הרחבה — ולכן כמעט כל מערך מסודר עובר דרכו.', true, 'Coach''s Clipboard — Basketball Terminology'),
  ('tactics', 'hard', 'מי הכדורסלן שנחשב למי שהביא את ה«יורו-סטפ» ל-NBA כשהצטרף לגולדן סטייט ב-1989?', array['שרונאס מרצ''ולוניס', 'מנו ג''ינובילי', 'דראז''ן פטרוביץ''', 'ולאדה דיבאץ'], 0, 'ג''ינובילי לא המציא את המהלך — הוא רק זה שגרם לכל העולם להכיר אותו, שנים אחר כך.', true, 'Sportscasting / ESPN / MasterClass — Euro step origins'),
  ('tactics', 'medium', 'איזו קבוצה זוהתה עם פילוסופיית ההתקפה «שבע שניות או פחות»?', array['פיניקס סאנס של מייק ד''אנטוני', 'סן אנטוניו ספרס של פופוביץ''', 'דטרויט פיסטונס', 'יוטה ג''אז של סטוקטון ומאלון'], 0, 'הרעיון היה לזרוק תוך שבע שניות מקבלת הכדור — היום כמעט כל ה-NBA משחקת ככה, אבל אז זה נראה מטורף.', true, 'The Ringer / ClutchPoints — Seven Seconds or Less Suns'),
  ('tactics', 'hard', 'איזה מאמן הפך את התקפת «ארבע הפינות» למפורסמת, עד שהיא זירזה את הכנסת שעון הזריקות לכדורסל הקולג''?', array['דין סמית''', 'בוב נייט', 'ג''ון ווּדן', 'פיל ג''קסון'], 0, 'ה-NCAA הכניסה שעון זריקות בעונת 1985/86 בין השאר בגללה — בלי שעון, קבוצה מובילה יכלה פשוט לכדרר עד הסוף.', true, 'ESPN / Basketball For Coaches — Four Corners offense'),
  ('tactics', 'medium', 'למה נשרק «מסך לא חוקי» (moving screen)?', array['מעמיד המסך זז או נשען ברגע המגע במקום לעמוד יציב', 'המסך הועמד מחוץ לקשת השלוש', 'הועמדו שני מסכים ברצף לאותו שחקן', 'המסך הועמד לשחקן שאין לו כדור'], 0, 'רגליו של החוסם חייבות להיות מקובעות ברגע המגע — צעד קטן אחד לצד הופך את המסך לעבירה התקפית.', true, 'FIBA Official Basketball Rules 2024 — screening'),
  ('tactics', 'medium', 'מה תפקידו של חצי העיגול המצויר מתחת לסל (restricted area)?', array['בתוכו לא תישרק עבירה התקפית על מגן שעומד מתחת לסל', 'בתוכו אסור לזרוק זריקת שלוש נקודות', 'בתוכו נספרות שלוש השניות בלבד', 'בתוכו אסור לתפוס ריבאונד התקפי'], 0, 'הקשת נועדה למנוע ממגנים לעמוד ממש מתחת לטבעת ולחטוף עבירה — כלומר, לעודד פריצות לסל.', true, 'FIBA Official Basketball Rules 2024 — no-charge semi-circle'),
  ('tactics', 'medium', 'מהו «גולטנדינג»?', array['נגיעה בכדור בזמן שהוא בדרכו מטה אל הסל', 'נגיעה ברשת בזמן שהכדור נכנס', 'חסימת מסירה גבוהה מעל הראש', 'עמידה בתוך הרחבה יותר משלוש שניות'], 0, 'הכלל נולד בגלל שחקנים גבוהים במיוחד שפשוט קטפו כדורים מהאוויר מעל הטבעת — ומאז אסור לגעת בכדור מרגע שהוא מתחיל לרדת.', true, 'Wikipedia — Goaltending (basketball) / NBA Rule No. 11'),
  ('tactics', 'medium', 'באיזו מסגרת קיימת עבירת «שלוש שניות הגנתית»?', array['ב-NBA', 'בפיב"א', 'בכל הליגות בעולם', 'רק בכדורסל הקולג'' בארה"ב'], 0, 'ה-NBA הוסיפה אותה לקראת עונת 2001/02, בדיוק כשהתירה סוף-סוף הגנת אזור — כדי שסנטרים לא ישבו בצבע כל ההתקפה.', true, 'Wikipedia — Defensive three-second violation / Illegal defense'),
  ('tactics', 'hard', 'מהו «של דריל» (shell drill), אחד התרגילים הנפוצים באימוני הגנה?', array['תרגיל 4 נגד 4 שמלמד עמדות עזרה, דחיקה ורוטציות', 'תרגיל זריקות רצוף מחמש עמדות בקשת', 'תרגיל ריצות סיבולת בין הקווים', 'תרגיל מסירות בזוגות מול הקיר'], 0, 'כל מסירה של ההתקפה מחייבת את ארבעת המגנים לזוז יחד — ובדיוק שם, ברגע התזוזה, נשברות רוב ההגנות.', true, 'Basketball For Coaches / Hoop Student — Shell Drill')
