-- =====================================================================
-- CourtSide — מאגר שאלות הכדורסל  ·  12.8.2026
--
-- 320 שאלות בעברית, שנכתבו לפי שמונה קטגוריות ועברו **אימות עובדתי
-- עצמאי**: כל שאלה נבדקה בידי בודק שלא כתב אותה, שתפקידו היה למצוא
-- טעויות. 11 שאלות נפסלו ולא נכנסו לכאן — בהן «צלילה = עבירה טכנית»
-- (מאז שינוי חוקי פיב"א ב-2024 זו אזהרה בפעם הראשונה), ושאלה שלימדה
-- שפסילה ב-NBA היא בחמש עבירות במקום בשש.
--
-- ⚠ **הקובץ הזה מכיל את התשובות הנכונות.** הוא בטוח רק משום שלטבלת
--   game_questions אין מדיניות SELECT לשחקן — ראה supabase_game_quiz_12_8.sql.
--   אל תוסיף לה מדיניות קריאה.
--
-- אידמפוטנטי: on conflict (q) do nothing. אפשר להריץ שוב אחרי שנוסיף
-- שאלות, ורק החדשות ייכנסו.
-- דורש: supabase_game_quiz_12_8.sql
-- =====================================================================

do $dep$
begin
  if to_regclass('public.game_questions') is null then
    raise notice '  ✋ עצור: game_questions לא קיימת — הרץ supabase_game_quiz_12_8.sql.';
  end if;
end $dep$;

on conflict (q) do nothing;

do $mig$
begin
  begin
    perform public.mark_migration('supabase_game_quiz_bank_12_8.sql');
  exception when others then null;
  end;
end $mig$;

notify pgrst, 'reload schema';

