--         from public.game_questions group by 1,2 order by 1,2;
--
--  2) **הבדיקה הקריטית** — מחשבון שחקן אמיתי בדפדפן:
--       select * from public.game_questions;
--     חייב להחזיר 0 שורות. אם חזרו שאלות — התשובות דלפו.
--
--  3) בניית חידון ניסיון (אדמין):
--       select public.game_build_quiz('חידון בדיקה', 8);
